INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_ssh-bruteforce', 'soc', 'triage', 'fresher', 'An alert fires: several failed SSH logins from one IP, then a successful one. What do you do first?', 'Scope before acting. Which account succeeded, is the source internal or external, and does that account normally sign in from there. Then look at what the session did afterwards, especially sudo or any new key added. The failure that sinks candidates is calling it a brute force and closing it without reading what happened after the success.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_ssh-bruteforce_f1', 'q_soc_fresher_ssh-bruteforce', 1, 'The success was on a different account from the failures. Does that change your read?', 'It makes it worse. Failures on one account and a success on another points at spraying across accounts, or at an attacker who already had working credentials while the failures were noise. The next question is what else that account touched and whether there were quiet successes you never alerted on.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_ssh-bruteforce_f2', 'q_soc_fresher_ssh-bruteforce', 2, 'The account belongs to a developer who says it was him. How do you verify?', 'Do not take the word alone, and do not treat doubting him as an accusation. Match the source address against his known locations and VPN logs, check the client version, and line the timing up against his working hours. Even if he was working, three failures on somebody else''s account still needs explaining.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_ids-vs-ips', 'soc', 'detection', 'fresher', 'What is the difference between an IDS and an IPS?', 'An IDS observes and alerts; an IPS sits inline and can drop. The difference that matters operationally is consequence: a false positive on an IDS is noise, a false positive on an IPS is an outage. That is why signatures go out in detect mode first and get promoted to block only once the noise is understood.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_ids-vs-ips_f1', 'q_soc_fresher_ids-vs-ips', 1, 'Your IPS is dropping legitimate traffic. What do you change first?', 'Move the offending signature to alert-only. Not the whole policy, and not the device. That stops the damage while keeping visibility, and gives you the traffic to decide whether to tune the rule, exempt the source, or fix the application that is tripping it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_ids-vs-ips_f2', 'q_soc_fresher_ids-vs-ips', 2, 'Who signs off on that change, and what goes in the ticket?', 'Whoever owns the control, with the application owner informed. The ticket records which rule, what traffic it matched, what the temporary state is, when it will be reviewed, and who approved it. A tuning change with no review date quietly becomes a permanent blind spot.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_phishing-report', 'soc', 'phishing', 'fresher', 'A user reports a phishing email. Walk me through what you do.', 'Preserve the original with full headers before anything else. Pull sender, reply-to, originating address, authentication results, links and attachments, and detonate anything live in a sandbox rather than on your own machine. Then find out who else received it and whether anyone interacted.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_phishing-report_f1', 'q_soc_fresher_phishing-report', 1, 'The user already clicked. What changes?', 'It stops being analysis and becomes containment. Find out what the page asked for and whether credentials went in. If they did, reset the password and invalidate active sessions and tokens, not just the password, then check for mailbox rules created after the click, which is the usual first move after a mailbox compromise.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_phishing-report_f2', 'q_soc_fresher_phishing-report', 2, 'How do you find everyone else who got it?', 'Search the mail platform by sender, originating address and URL, not just the exact subject, because the campaign varies it. Then separate delivered from opened from clicked, purge what is left in mailboxes, and report those three numbers, because that is what the business will ask for.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_url-to-render', 'soc', 'fundamentals', 'fresher', 'You type a URL and press enter. Walk me through what happens, and tell me where you would look if it broke.', 'DNS resolution, TCP connection, TLS handshake, HTTP request, response, render. The interviewer is not testing recall; they are testing whether you can hang investigation on the model. A strong answer names what fails at each step and what you would check to prove it, rather than reciting the sequence.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_url-to-render_f1', 'q_soc_fresher_url-to-render', 1, 'It resolves but times out. Which layer do you suspect?', 'Resolution worked, so the problem is after DNS: routing, a firewall silently dropping rather than rejecting, or a dead service. A reject gives you a fast refusal; a timeout usually means something is dropping packets on purpose. Trace the path and test the port directly rather than reloading the browser.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_url-to-render_f2', 'q_soc_fresher_url-to-render', 2, 'It loads but the browser warns about the certificate. What are the possibilities, in order?', 'Most likely the dull ones: expired certificate, wrong hostname, or an incomplete chain. Then an inspection proxy injecting its own certificate, which is normal on a corporate network. Interception by someone you did not invite is real but last, and you confirm it by comparing the issuer with what you expect, not by guessing.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_unknown-alert', 'soc', 'process', 'fresher', 'You are on L1 and an alert type you have never seen before lands in the queue. Walk me through it.', 'The honest answer is a method, not knowledge. Read what the rule is actually looking for, find the raw events behind it, establish whether the behaviour is normal for that host or account, and check whether it has fired before and how it was closed. Escalate with what you found, not with the alert forwarded untouched.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_unknown-alert_f1', 'q_soc_fresher_unknown-alert', 1, 'Nobody senior is online and it looks serious. What do you do?', 'Act on the reversible things and escalate the rest. Collect and preserve evidence, follow whatever containment the runbook already authorises for L1, and page according to the escalation path rather than waiting for a shift change. Err towards waking someone: an unnecessary call costs far less than a missed hour.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_unknown-alert_f2', 'q_soc_fresher_unknown-alert', 2, 'It turns out to be benign. Does anything still need doing?', 'Yes, or you will spend the rest of the year reading it. Write down why it was benign in terms specific enough for the next analyst, and either tune the rule or record that it stays noisy for a reason. An alert that keeps arriving with no decision attached is how a queue stops being read at all.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_threat-vuln-risk', 'soc', 'fundamentals', 'fresher', 'What is the difference between a vulnerability, a threat and a risk?', 'A vulnerability is a weakness, a threat is something that could exploit it, and risk is the combination weighed by likelihood and impact. The useful version is practical: an unpatched server is a vulnerability, a group that exploits that software is a threat, and the risk depends on whether that server is exposed and what it holds.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_threat-vuln-risk_f1', 'q_soc_fresher_threat-vuln-risk', 1, 'Two servers have the same critical CVE. One is in the DMZ, one is on an isolated test VLAN. Same risk?', 'No, and this is exactly why severity alone does not prioritise anything. Same vulnerability, very different exposure and impact. Patch the exposed one first and say so in those terms, because that is the sentence that gets you taken seriously by people who own uptime.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_threat-vuln-risk_f2', 'q_soc_fresher_threat-vuln-risk', 2, 'The test VLAN turns out to have a route to production. Now what?', 'The risk rating was wrong because the network diagram was wrong, which is the normal case. Re-rate it, patch it, and then raise the route itself as the bigger finding: an isolated segment that is not isolated invalidates every other risk decision that assumed it was.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_what-siem-does', 'soc', 'tooling', 'fresher', 'What is a SIEM actually doing, and what is it not doing?', 'It collects logs from many sources, normalises them into a common shape, correlates across them, and raises alerts on rules you wrote. What it is not doing is understanding your environment or finding things nobody asked it to look for. A SIEM with no tuned rules and no log sources that matter is an expensive search bar.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_what-siem-does_f1', 'q_soc_fresher_what-siem-does', 1, 'Leadership asks why the SIEM missed something. How do you answer?', 'Find out which of three things failed before answering: the log never arrived, the log arrived but no rule looked for that behaviour, or a rule fired and nobody acted. They need completely different fixes, and saying "the SIEM missed it" hides which one it was. Answer with the specific gap and what closes it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_what-siem-does_f2', 'q_soc_fresher_what-siem-does', 2, 'Which log sources would you fight for first, with a limited budget?', 'Identity and endpoint, in that order. Authentication tells you who did what, and endpoint telemetry tells you what actually ran. Firewall and proxy logs are high volume and easy to buy but answer fewer questions on their own. Say what you would cut, not just what you would add, because that is the real question.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_beaconing-host', 'soc', 'triage', 'fresher', 'A laptop is reaching out to the same external address every sixty seconds, give or take a few. What do you check?', 'Regular intervals with small jitter mean automation, not a person. Establish which process is making the connection, what the destination is and how long it has been running, and whether other hosts do the same. Beaconing is a shape, and plenty of legitimate software has that shape too.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_beaconing-host_f1', 'q_soc_fresher_beaconing-host', 1, 'The destination is a well-known cloud provider. Does that clear it?', 'No. Hosting on a reputable provider is cheap and extremely common for command and control, precisely because the domain looks harmless and often cannot be blocked wholesale. Judge it on the process making the call and what it sends, not on who owns the address range.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_beaconing-host_f2', 'q_soc_fresher_beaconing-host', 2, 'It turns out to be a legitimate agent nobody documented. What do you do with that?', 'Close the alert and then fix the real problem, which is that an unknown agent was running on a managed laptop. Get it into the asset and software inventory, and raise that the inventory is incomplete. The next unexplained beacon should be answerable in minutes, not hours.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_why-soc', 'soc', 'behavioural', 'fresher', 'Why security, and why a SOC role specifically?', 'The weak answer is "I am passionate about cybersecurity". The strong one is concrete: something you actually did, what it taught you, and why the SOC in particular rather than security in general. Mentioning that you want the volume and pattern exposure a SOC gives early in a career shows you understand what the job is.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_why-soc_f1', 'q_soc_fresher_why-soc', 1, 'Where do you want to be in three years? Say pentesting, and watch what happens.', 'Be honest, because the usual lie is obvious and they have heard it. If you want to move towards hunting, detection engineering or offensive work, say so and say what the SOC gives you on the way there. Managers plan around real ambitions. They lose people who pretended not to have any.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_why-soc_f2', 'q_soc_fresher_why-soc', 2, 'This role is on rotating shifts including nights. Still interested?', 'Answer the question that is really being asked, which is whether you will quit in four months. Say plainly whether nights work for you. Agreeing to something you cannot sustain is worse for you than for them, and the ones who handle this honestly in the room are the ones who last.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_signed-binary', 'soc', 'endpoint', 'mid', 'Your EDR flags a signed binary behaving unusually. How do you triage it?', 'A valid signature says who built it, not that this execution is safe. Look at the behaviour chain: parent process, command line, network destinations, files written, persistence created. Signed system tools get abused for living-off-the-land execution precisely because reputation scoring waves them through.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_signed-binary_f1', 'q_soc_mid_signed-binary', 1, 'The signature is valid and the vendor is well known. Still suspicious?', 'Yes, if the behaviour does not match what that binary exists to do. A known-good tool launched by an unusual parent, with arguments that fetch a remote payload, is a standard abuse pattern. The question is whether this execution is expected on this host, not whether the file is malicious in general.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_signed-binary_f2', 'q_soc_mid_signed-binary', 2, 'You decide to contain. What exactly, and what do you tell the business?', 'Isolate at the network level while keeping your own access, rather than powering off and losing memory. Block the destination at the egress point. Then tell the business which host, what the user can no longer do, what you need from them, and when you will next update them. Vague updates are what turn an incident into a political problem.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_rule-tuning', 'soc', 'tuning', 'mid', 'How do you tune a noisy detection rule without going blind to the thing it was built for?', 'Start from what the rule is meant to catch, then measure what it is actually matching. Narrow on the attribute that separates benign from malicious, usually a specific process, account or destination, rather than lowering severity or widening the window. Record the exclusion and the reason, so the next analyst can see the gap you accepted.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_rule-tuning_f1', 'q_soc_mid_rule-tuning', 1, 'The noise comes from one application the business will not change. Now what?', 'Scope the exclusion as tightly as the application allows: that service account, on those hosts, to those destinations. Add a narrower compensating rule that would still fire if the excluded pattern were abused, and write down the residual risk so it is a decision on record rather than a silent hole.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_rule-tuning_f2', 'q_soc_mid_rule-tuning', 2, 'Six months later, how do you know the tuning is still right?', 'Review exclusions on a schedule and test them. Confirm the application still behaves the way the exclusion assumes, and validate that the rule still fires on the original behaviour using an atomic test. An exclusion nobody has revisited is a control nobody can vouch for.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_coverage-real', 'soc', 'detection', 'mid', 'How do you know your detection coverage is real and not just a long list of rules?', 'Map detections to attacker behaviours rather than counting rules, then test them. A framework like ATT&CK gives you the map; atomic tests tell you whether the rule actually fires in your environment with your log sources. Coverage you have never fired is a claim, not a control.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_coverage-real_f1', 'q_soc_mid_coverage-real', 1, 'Your map shows green across the board. Do you believe it?', 'No, and saying so is the right answer. A green map usually means coverage was recorded when the rule was written, not verified since. Log sources get dropped, agents fall off hosts, and parsers break quietly. Treat the map as a to-test list rather than a report card.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_coverage-real_f2', 'q_soc_mid_coverage-real', 2, 'You find a technique you genuinely cannot detect. What do you do with it?', 'Write it down as a known gap with what it would take to close it, which is usually a log source or a licence rather than cleverness. Then look for a compensating detection one step earlier or later in the chain. A documented gap with an owner beats an undocumented one that someone assumes is covered.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_incident-walkthrough', 'soc', 'behavioural', 'mid', 'Walk me through an incident you actually handled, start to finish.', 'Pick one you can tell honestly, including what went wrong. Structure it: how it was detected, what you first thought, what changed your mind, what you contained, and what the organisation changed afterwards. The part interviewers listen hardest for is the moment your first theory was wrong and how you noticed.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_incident-walkthrough_f1', 'q_soc_mid_incident-walkthrough', 1, 'What would you do differently?', 'Have a real answer. "Nothing" reads as either inexperience or no reflection. Name something specific, such as containing before fully scoping and losing visibility, or not getting the business on a call early enough, and say what you changed afterwards so it did not repeat.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_incident-walkthrough_f2', 'q_soc_mid_incident-walkthrough', 2, 'Who did you escalate to, and when?', 'They are checking whether you understand that escalation is a decision with a cost both ways. Name the trigger you used, not just the person. Candidates who escalate everything are as hard to staff around as candidates who escalate nothing.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_siem-cost', 'soc', 'tooling', 'mid', 'Your SIEM ingest cost has doubled and you have been told to cut it. What goes?', 'Start from which logs have ever been used in a detection or an investigation, because the bill usually hides a few enormous, useless sources. Cut volume before cutting sources: filter noisy event types, sample what is only ever used in aggregate, and move long-tail data to cheaper storage you can still search when it matters.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_siem-cost_f1', 'q_soc_mid_siem-cost', 1, 'Finance wants you to drop endpoint logs because they are the biggest line.', 'Push back with what breaks, in their language: name the detections that stop working and the investigations that become impossible. Then offer the alternative, which is usually filtering at the agent and shortening hot retention rather than dropping the source. Agreeing quietly and losing the capability silently is the failure mode.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_siem-cost_f2', 'q_soc_mid_siem-cost', 2, 'Six months later nobody remembers what was cut. How do you prevent that?', 'Record the cut as a risk decision with an owner and a review date, not as a config change in a ticket. Put the affected detections in the same record. When the next incident hits a blind spot, the question becomes who accepted it and when, which is a fair conversation, rather than why security missed it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_shift-handover', 'soc', 'process', 'mid', 'How do you hand over a live incident at shift change?', 'Written, not verbal, and structured: what is known, what is believed but unconfirmed, what has been done including anything you changed, what is pending and who owns it, and the next decision point. The common failure is handing over conclusions without the evidence, so the next shift cannot tell what to re-check.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_shift-handover_f1', 'q_soc_mid_shift-handover', 1, 'The incoming analyst disagrees with your read. What should happen?', 'Good, that is the handover working. Separate what is observed from what is inferred and let them re-examine the inference against the evidence. The handover note should make that possible without you in the room. If disagreement feels like a challenge rather than a check, the process is broken.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_shift-handover_f2', 'q_soc_mid_shift-handover', 2, 'What do you deliberately leave out?', 'Speculation dressed as fact, and the running commentary. Keep the timeline, the evidence and the open decisions. A handover that includes every thought anyone had during the shift is one nobody reads, which is the same as no handover at all.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_closed-wrongly', 'soc', 'process', 'mid', 'An analyst on your team closed a true positive as benign. How do you handle it?', 'Handle the incident first, then the cause. Reopen, scope what was missed and how long it ran. Then look at why it was closable: was the evidence genuinely ambiguous, was the queue too deep to read properly, or was the runbook wrong. One analyst making one call is almost never the real finding.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_closed-wrongly_f1', 'q_soc_mid_closed-wrongly', 1, 'It turns out the runbook told them to close it. Now what?', 'Then the analyst did their job and the runbook is the defect. Fix it, and say so publicly to the team, because the alternative teaches everyone that following the process is risky. That lesson costs far more than this incident did.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_closed-wrongly_f2', 'q_soc_mid_closed-wrongly', 2, 'How do you catch this class of mistake earlier next time?', 'Sample closed alerts, not just open ones. A small weekly review of a random handful of benign closures catches both bad runbooks and queue pressure, and it does it without singling anyone out. Reviewing only what blew up means you only ever learn from the ones that blew up.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_read-auth-line', 'soc', 'log-reading', 'fresher', 'Here is one line from an auth log: `Failed password for invalid user admin from 203.0.113.5`. What does it tell you, and what does it not?', 'It tells you someone tried to log in as admin, that the account does not exist on this host, that it came from that IP, and that it failed. It does not tell you whether this is one stray attempt or one of thousands, whether it is automated or aimed at you, or whether anything succeeded. A candidate who has read logs separates the fact in the line from the story they want to put around it.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_read-auth-line_f1', 'q_soc_fresher_read-auth-line', 1, 'The same IP has four hundred of these in ten minutes. Does your read change?', 'The volume says spray or brute force, not a targeted human, and invalid user says they are guessing account names that do not exist. Still low severity on its own. The thing I now look for is a line that is not a failure.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_read-auth-line_f2', 'q_soc_fresher_read-auth-line', 2, 'There is one Accepted password line in the middle of them. Now what?', 'That flips it. A success in the middle of a brute force is the whole event. I scope that account, that source, and that session, and I start looking for what they did after they were in, not at the failures before.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_internet-is-slow', 'soc', 'network', 'fresher', 'A user says the internet is slow. From a SOC seat, what could that mean to you that it does not mean to them?', 'To them it is an annoyance. To a SOC it is a possible symptom: a link saturated by exfiltration, a host beaconing hard, a denial-of-service, or a proxy failing. I do not diagnose the complaint, I ask what the traffic looks like, because slow is sometimes the only thing a user notices when something is leaving the network.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_internet-is-slow_f1', 'q_soc_fresher_internet-is-slow', 1, 'Where do you look first?', 'Egress: the proxy, firewall, or netflow for throughput and top talkers, and whether anything is going somewhere it should not. The complaint points at the link; the answer is in what is using it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_internet-is-slow_f2', 'q_soc_fresher_internet-is-slow', 2, 'The top talker is one internal host sending to one external IP, a steady two megabytes a second for an hour. Your read?', 'A steady, long, one-to-one transfer is exfiltration-shaped, not browsing. I scope the host, check the destination''s reputation and who it belongs to, and find the process doing it before I decide it is backup traffic.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_encoded-powershell', 'soc', 'encoding', 'fresher', 'You see `powershell -enc SQBFAFgA...` in a process-creation log. What is it, and what do you do?', 'The -enc flag runs base64-encoded PowerShell, where the base64 decodes to UTF-16LE text. It is a common obfuscation but not proof of anything on its own, since admins and installers use it too. I decode it and judge it on what it actually does, rather than reacting to the flag.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_encoded-powershell_f1', 'q_soc_fresher_encoded-powershell', 1, 'Decoded, it is `IEX (New-Object Net.WebClient).DownloadString(''http://...'')`. Severity?', 'High. That is download-and-execute from an external URL: pull code off the internet and run it in memory. I isolate the host, grab the URL and what it served, and work out what ran and under whose account.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_encoded-powershell_f2', 'q_soc_fresher_encoded-powershell', 2, 'The user is a developer who does this every day. Still high?', 'The context lowers it but does not zero it. I confirm it is their known pattern and not a lookalike, because a thing this user does daily is also exactly how a real one hides in plain sight.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_windows-event-ids', 'soc', 'windows', 'fresher', 'Which Windows event IDs do you actually watch, and why those?', 'The ones that show access, privilege, and persistence, not a memorised list: 4625 and 4624 for failed and successful logons with their type, 4672 for a logon granted special privileges, 4688 for process creation, 4720 for a new account, 7045 for a new service. I would rather know cold why each of those matters than recite twenty I have never alerted on.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_windows-event-ids_f1', 'q_soc_fresher_windows-event-ids', 1, 'You see 4672 for a service account at three in the morning. Interesting?', 'Potentially. A special-privilege logon for a service account off-hours is worth a look, but it depends on whether that account is meant to run scheduled or interactive work. The question is whether this matches how it normally behaves.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_windows-event-ids_f2', 'q_soc_fresher_windows-event-ids', 2, 'How do you tell a scheduled task from someone logging in at the keyboard?', 'The logon type: 2 is interactive, 3 network, 4 batch, 5 service, 10 remote desktop. The type is the tell, and it is why I said with their type rather than just the event number.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_mitre-day-to-day', 'soc', 'mitre', 'mid', 'How do you actually use MITRE ATT&CK day to day, beyond putting it on a slide?', 'As a coverage map and a shared language. I map detections to techniques to find the gaps, and I tag alerts with the technique so triage knows what stage it is. What I do not do is treat it as a checklist to cover everything, which is how you end up with a wall of weak detections. Someone who has used it talks about gaps and trade-offs, not completeness.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_mitre-day-to-day_f1', 'q_soc_mid_mitre-day-to-day', 1, 'Your manager wants a hundred percent ATT&CK coverage. Your response?', 'Coverage is not a percentage. Some techniques your telemetry cannot see, some are not worth the noise, and a detection that exists only to tick a box is worse than an honest gap. I would prioritise by the threats that actually target us and the data we already have.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_mitre-day-to-day_f2', 'q_soc_mid_mitre-day-to-day', 2, 'A technique you genuinely cannot detect: what do you do with it?', 'Document the gap, decide whether the telemetry to close it is worth adding, and compensate elsewhere in the chain if it is not. A written, known gap is an asset. A fake detection over it is a liability, because it tells you you are safe when you are not.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_lateral-in-logs', 'soc', 'lateral-movement', 'mid', 'What does lateral movement actually look like in your logs, as opposed to in a diagram?', 'A pattern across hosts, not a single event: one account authenticating to many machines in a short window, type-3 network logons to systems it never normally touches, use of admin shares, PsExec or WMI, and new service installs appearing on the targets. The arrow in the diagram is, in the data, a spray of ordinary-looking logons that are wrong only in aggregate.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_lateral-in-logs_f1', 'q_soc_mid_lateral-in-logs', 1, 'If you could weight one signal above the rest, which?', 'An account authenticating to hosts outside its normal set, especially with administrative rights. The specific tool matters less than the deviation from what that account usually touches.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_lateral-in-logs_f2', 'q_soc_mid_lateral-in-logs', 2, 'You have no baseline of what is normal. Now what?', 'I build a rough one from the data I do have, who normally logs into what, or I lean on the structural tells that are suspicious regardless: a service install on a workstation, PsExec between peers, a brand-new admin account. Some things do not need a baseline to look wrong.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_two-alerts-one-minute', 'soc', 'triage', 'mid', 'Same minute, one analyst: a malware detection auto-quarantined on a finance laptop, and a single failed VPN login for the CFO. Which do you take first, and why?', 'The VPN one, briefly. Auto-quarantine means the EDR has already acted, so that laptop is probably contained; a failed login on a high-value account could be the front edge of something that is not contained yet. I prioritise by what is still live and who it touches, not by which label sounds scarier.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_two-alerts-one-minute_f1', 'q_soc_mid_two-alerts-one-minute', 1, 'The failed VPN login was the CFO mistyping their password, confirmed. Back to the malware?', 'Yes, and now I treat it properly: what the sample was, how it arrived, whether it ran before quarantine caught it, and whether anything else on that host is affected.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_two-alerts-one-minute_f2', 'q_soc_mid_two-alerts-one-minute', 2, 'How do you know the quarantine actually held?', 'I check the EDR action succeeded, the file is neutralised, no child processes spawned before it was caught, and there were no network callouts. Quarantined in the console is a claim; I want to see it was quarantined in time.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_soc-board-metrics', 'soc', 'metrics', 'mid', 'You are asked for SOC metrics for a board deck. What do you report, and what do you refuse to report?', 'I report things that reflect outcomes: how fast we detect and respond, our true-positive rate, gaps we have closed. I refuse vanity numbers like alerts processed or threats blocked, which reward noise and sound impressive while saying nothing. Part of the job is protecting the board from a number that would mislead them.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_soc-board-metrics_f1', 'q_soc_mid_soc-board-metrics', 1, 'The board loves threats blocked: two million. You know it is mostly firewall noise. What do you do?', 'I reframe it honestly: that figure is traffic, not threats, and I offer a metric that means something, even if the number is smaller and less flattering. A true small number beats an impressive false one.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_soc-board-metrics_f2', 'q_soc_mid_soc-board-metrics', 2, 'Your mean-time-to-respond looks bad this quarter because of one long incident. Report it?', 'Yes, with the context. Hiding it is how metrics lose trust. One explained outlier is more credible than a smooth average someone quietly massaged, and the board can handle the truth better than finding out later.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_severity-gut-vs-tool', 'soc', 'severity', 'fresher', 'How do you decide an alert''s severity when the tool''s rating and your own read disagree?', 'I go by what is actually at stake, not the label the tool shipped with. Severity is impact times how live it still is: what the affected asset is worth, who it touches, and whether the thing is still happening or already contained. The tool''s rating is a starting opinion from someone who never saw your environment, so I weigh it and then decide, and I write down why I overrode it.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_severity-gut-vs-tool_f1', 'q_soc_fresher_severity-gut-vs-tool', 1, 'The tool says critical, you think it is noise. You are junior. Do you downgrade it?', 'I investigate enough to be sure before I touch the rating, and if I downgrade I record exactly why and leave the trail. Being junior means I show my working, not that I defer blindly, because a critical waved away without evidence is how real ones get missed.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_severity-gut-vs-tool_f2', 'q_soc_fresher_severity-gut-vs-tool', 2, 'You think it is critical, the tool says low. What do you do?', 'Escalate on my read, not the tool''s. Under-rating is the more dangerous mistake, so I would rather be wrong raising it than wrong burying it, and I make the case with what I found rather than just a feeling.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_handed-a-suspicious-file', 'soc', 'malware', 'fresher', 'A user sends you a file they think is malware. What do you do with it, and what do you not do?', 'I do not open it on my own machine, and I do not double-click it anywhere that matters. I preserve it, hash it and check the hash against known-bad, look at it in a sandbox or detonation environment rather than live, and keep it contained the whole time. The mistake that ends careers early is running the thing you are trying to analyse on the box you are analysing it from.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_handed-a-suspicious-file_f1', 'q_soc_fresher_handed-a-suspicious-file', 1, 'The hash is unknown to every feed. Is it safe, then?', 'No. Unknown means nobody has reported it yet, which is exactly what a fresh or targeted sample looks like. I still detonate it in a sandbox and judge it by behaviour, because being new to the feeds is a reason for more caution, not less.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_handed-a-suspicious-file_f2', 'q_soc_fresher_handed-a-suspicious-file', 2, 'How do you get it off the user''s machine without making things worse?', 'Carefully and with the original preserved: copy it in a contained way rather than forwarding it around, and if the machine might already be affected I treat the whole host, not just the file. Emailing malware to your team to ''take a look'' is how it spreads inside the walls.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_spf-dkim-dmarc', 'soc', 'email-auth', 'fresher', 'SPF, DKIM and DMARC: what does each actually tell you when you are staring at a suspicious email?', 'SPF says whether the sending server was allowed to send for that domain. DKIM says whether the message was signed by the domain and not altered in transit. DMARC ties the two to the visible From address and tells the receiver what to do when they fail. Together they answer did this really come from who it claims, and a fail on the From domain is a strong tell, though a pass does not make the content safe.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_spf-dkim-dmarc_f1', 'q_soc_fresher_spf-dkim-dmarc', 1, 'The email passes all three. Does that mean it is legitimate?', 'No. It means it genuinely came from that domain, not that the domain is trustworthy or uncompromised. A real but hacked account, or a lookalike domain that set its own records up correctly, passes all three while still being an attack.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_spf-dkim-dmarc_f2', 'q_soc_fresher_spf-dkim-dmarc', 2, 'DMARC says the domain''s policy is ''none''. What does that tell you?', 'That the owner is monitoring but not enforcing, so a spoofed message still gets delivered rather than rejected or quarantined. It is a configuration gap on their side, and it is why I cannot lean on DMARC alone to have stopped the mail.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_fresher_signs-of-data-leaving', 'soc', 'exfil', 'fresher', 'What are the signs of data leaving that you would actually catch, and which ones would you miss?', 'I would catch the obvious shapes: large or steady outbound transfers, uploads to personal cloud storage, a host talking to a destination it never did, odd volumes at odd hours. I would miss slow, low exfiltration dribbled out under the noise, data hidden in protocols I do not inspect like DNS or encrypted channels, and anything that leaves on a USB stick or a phone camera, which never touches the network at all.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_signs-of-data-leaving_f1', 'q_soc_fresher_signs-of-data-leaving', 1, 'How would you catch the slow, low version?', 'By baselining normal for each host and alerting on deviation over time rather than on a single big spike, and by watching cumulative volume to a destination, not just instantaneous rate. The patient attacker beats a threshold that only looks at one moment.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_signs-of-data-leaving_f2', 'q_soc_fresher_signs-of-data-leaving', 2, 'The data left over DNS. How would that even work?', 'By encoding the data into the names being looked up, so a stream of long odd subdomain queries to one domain carries the payload out a channel almost nobody blocks. The tell is the volume and shape of the DNS, which is why those TXT and long-name patterns are worth alerting on.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_using-a-feed-without-drowning', 'soc', 'threat-intel', 'mid', 'You are given a feed of malicious IPs and hashes. How do you use it without drowning?', 'Not by blocking everything on sight. I prioritise by relevance and confidence: which indicators match threats that actually target us, how fresh and how reliable the source is, and whether an indicator is specific enough to act on. Then I use it to enrich and hunt rather than to auto-block a million stale IPs, because a feed treated as a blocklist becomes noise and outages, not defence.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_using-a-feed-without-drowning_f1', 'q_soc_mid_using-a-feed-without-drowning', 1, 'Why not just block every IP on the list?', 'Because the list is large, stale, and shared, so it includes recycled addresses now serving legitimate sites, and blocking them causes outages while the real attacker has already moved to a new one. Indicators age badly, so I use them to spot and investigate, not as a permanent wall.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_using-a-feed-without-drowning_f2', 'q_soc_mid_using-a-feed-without-drowning', 2, 'What makes one indicator more useful than another?', 'How specific and how durable it is. A file hash or a unique domain is precise and worth acting on; a shared IP or a common user-agent is weak and ages fast. The pyramid-of-pain idea applies: the indicators that cost the attacker the most to change are the ones worth building detection on.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_isolate-now-or-watch', 'soc', 'containment', 'mid', 'An endpoint is compromised. Do you isolate it now or watch it to learn more? Walk me through the call.', 'It is a trade between stopping the bleeding and understanding the wound. I isolate immediately when the risk of spread or data loss is live, which is most of the time. I hold off and watch only when containment is already partial, the threat is not actively moving, and the intelligence from watching is worth the risk, and even then with a hand on the switch. The default is contain, because a learning exercise that becomes a breach is a bad trade.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_isolate-now-or-watch_f1', 'q_soc_mid_isolate-now-or-watch', 1, 'What would make you choose to watch rather than isolate?', 'A contained-enough situation where isolating would tip off a sophisticated actor before I understand their scope, and where I have the monitoring to watch safely and pull the plug instantly. It is a senior call made with authority and a plan, not a junior analyst deciding to let an intrusion run.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_isolate-now-or-watch_f2', 'q_soc_mid_isolate-now-or-watch', 2, 'You isolate and the attacker had a second foothold you did not know about. What does that teach you?', 'That containment is scoping, not a single action: isolating one host is the start, and the job is to find everywhere else they are before declaring it over. One foothold almost always implies looking for others, so I widen rather than close out.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_buried-in-alerts', 'soc', 'operations', 'mid', 'Your team is buried in alerts. What do you change, structurally, beyond ''tune the rules''?', 'I treat the volume as a design problem, not a stamina problem. That means killing or tuning the detections that never produce a true positive, enriching alerts so an analyst sees context instead of hunting for it, grouping related alerts into one incident instead of fifty tickets, and automating the rote triage steps. The goal is fewer, richer alerts that each deserve a human, not a faster treadmill.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_buried-in-alerts_f1', 'q_soc_mid_buried-in-alerts', 1, 'Which alerts do you kill first?', 'The ones with a long history of firing and never being real: high volume, zero true positives, no path to tuning. Every one of those is tax on attention, and attention spent on noise is attention not spent on the alert that mattered. I kill them openly, with the data, not quietly.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_buried-in-alerts_f2', 'q_soc_mid_buried-in-alerts', 2, 'Is there a risk in turning detections off?', 'Yes, a blind spot, so I do not just delete, I decide: tune it, replace it with something that fires only on the real pattern, or accept and document the gap. The point is that a detection nobody can act on is already a blind spot pretending to be coverage.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_soc_mid_hunting-an-insider', 'soc', 'insider', 'mid', 'How is hunting an insider different from hunting an external attacker?', 'The insider already has legitimate access, so there is no break-in to catch and no foreign foothold to find. The signal is misuse of normal access: reaching data outside their role, at odd times, in odd volumes, staging things to leave, or behaviour that changes around an event like a resignation. It is quieter, more about deviation from a person''s own baseline than about known-bad, and it carries a human and legal weight an external hunt does not.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_hunting-an-insider_f1', 'q_soc_mid_hunting-an-insider', 1, 'What is the single hardest part?', 'Telling misuse from a normal person doing their job slightly unusually. The base rate of real insiders is tiny and the false-positive cost is high, because accusing an innocent employee has real consequences, so the bar for acting has to be careful and evidence-led.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_hunting-an-insider_f2', 'q_soc_mid_hunting-an-insider', 2, 'How do you keep an insider investigation from becoming a witch hunt?', 'Tight scope, documented reasons, need-to-know handling, and HR and legal in the loop from the start rather than an analyst quietly watching a colleague. The investigation is a controlled process with oversight, precisely because the power to surveil an employee is easy to abuse.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_tcp-handshake', 'network', 'tcp', 'fresher', 'Explain the TCP three-way handshake.', 'The client sends SYN with its initial sequence number, the server replies SYN-ACK acknowledging it and offering its own, the client replies ACK. The point is that both sides agree on sequence numbers and both prove they can receive, which is what makes blind spoofing hard. Say why it exists, not just the three words.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_tcp-handshake_f1', 'q_network_fresher_tcp-handshake', 1, 'You see thousands of SYNs with no completing ACKs. What is happening?', 'Half-open connections, so either a SYN flood or a scan. A flood is trying to exhaust the backlog; a scan is looking for open ports and usually comes with RSTs. Tell them apart by volume, how spread the sources are, and whether the destination ports vary or stay fixed.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_tcp-handshake_f2', 'q_network_fresher_tcp-handshake', 2, 'How would you confirm it, and what would you actually do?', 'Confirm with a capture and the host''s own connection-state counters rather than trusting the alert. Mitigation is SYN cookies, rate limiting at the edge, and upstream filtering once the volume exceeds your link. If it is a scan rather than a flood, the answer is blocking and investigating the source, not tuning the stack.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_stateful-firewall', 'network', 'firewalls', 'fresher', 'What is the difference between a stateful and a stateless firewall?', 'A stateless firewall judges each packet in isolation. A stateful one tracks connections, so return traffic for an established session is allowed without a matching inbound rule. Stateful is why you do not have to write a rule for every ephemeral port on the way back.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_stateful-firewall_f1', 'q_network_fresher_stateful-firewall', 1, 'Which goes at the perimeter, and why?', 'Stateful, because the perimeter is exactly where you need to tell solicited return traffic from unsolicited inbound traffic. A stateless filter there either blocks legitimate replies or forces rules so broad they stop meaning anything.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_stateful-firewall_f2', 'q_network_fresher_stateful-firewall', 2, 'What does stateful inspection cost you that stateless does not?', 'Memory and a finite connection table, which is itself a target: fill the table and the device starts dropping or fails open. It costs per-connection processing at high throughput, and it makes failover harder, because state has to be synchronised or every session breaks on cutover.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_dns-resolution', 'network', 'dns', 'fresher', 'Walk me through how a name gets resolved, and tell me where you would tamper with it if you were an attacker.', 'Browser cache, OS cache, configured resolver, then recursion from root to TLD to authoritative, with the answer cached at each hop by TTL. An attacker goes for whichever step is softest: the host file, the resolver setting, a registrar account, or cache poisoning. The caching is the interesting part, because it is what makes a bad answer stick.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_dns-resolution_f1', 'q_network_fresher_dns-resolution', 1, 'A user says one site is wrong but everyone else is fine. Where do you look?', 'Start local, because that is where the difference is. Host file, the resolver that machine is actually using, and any proxy or VPN in the path. Compare their answer against a known-good resolver from the same network, which tells you in one step whether it is the machine or the network.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_dns-resolution_f2', 'q_network_fresher_dns-resolution', 2, 'What does DNSSEC actually protect against, and what does it not?', 'It gives you integrity: the answer came from the zone owner and was not altered. It does not give you confidentiality, so the query is still visible, and it says nothing about whether the domain is trustworthy. A signed answer from a malicious domain is still perfectly valid.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_nat-investigation', 'network', 'addressing', 'fresher', 'What is NAT, and why does it make your job harder?', 'NAT rewrites addresses so many internal hosts share one public address. The investigative cost is that an external log showing your public address identifies the company, not the machine. Without NAT translation logs correlated by source port and exact timestamp, an abuse report is unactionable.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_nat-investigation_f1', 'q_network_fresher_nat-investigation', 1, 'You get an abuse report naming your public IP at 14:32. What do you need to find the host?', 'The translation logs for that window, plus the source port and ideally the destination, because the public address alone maps to hundreds of machines. If those logs are not kept, say so plainly: the honest answer is that you cannot identify the host, and the finding is the missing log.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_nat-investigation_f2', 'q_network_fresher_nat-investigation', 2, 'CGNAT at the ISP sits in front of you too. What does that change?', 'The same problem one layer up, and now it is someone else''s logs. It also means an external address in your own logs may be shared by many unrelated subscribers, so blocking or attributing on that address alone hits bystanders. Weight address-based indicators accordingly.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_tls-what-it-gives', 'network', 'crypto', 'fresher', 'HTTP versus HTTPS: what exactly does TLS give you, and what does it not?', 'Confidentiality in transit, integrity so content cannot be altered undetected, and authentication of the server through its certificate. What it does not give you is a safe site, a safe endpoint, or hidden metadata: the destination address and the hostname in SNI are still visible, and the data is plaintext again the moment it arrives.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_tls-what-it-gives_f1', 'q_network_fresher_tls-what-it-gives', 1, 'A phishing site has a valid padlock. Explain that to a user.', 'The padlock means the connection to that site is private, not that the site is honest. Certificates are free and issued in minutes to anyone who controls a domain, including attackers. Tell users to read the domain, not the lock, and stop teaching the lock as a safety signal.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_tls-what-it-gives_f2', 'q_network_fresher_tls-what-it-gives', 2, 'Your company inspects TLS at the proxy. What are you giving up?', 'You break end-to-end encryption on purpose, so the proxy becomes a single place where all plaintext exists and a very high-value target. You also create legal and privacy obligations around what is inspected, and you break certificate pinning in some apps. It is a real trade, and the honest answer names both sides.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_vpn-protects', 'network', 'remote-access', 'fresher', 'What is a VPN actually protecting against?', 'It protects traffic in transit across a network you do not trust, and for corporate use it puts the device inside a network boundary. That is it. It does not make the endpoint safe, it does not make you anonymous to the sites you visit, and a compromised laptop on a VPN is a compromised laptop with a route into the office.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_vpn-protects_f1', 'q_network_fresher_vpn-protects', 1, 'Everyone is remote. Is a VPN still the right model?', 'It is one model, and it has a known weakness: once you are in, you are inside. The alternative is per-application access with identity and device posture checked on every request, which removes the all-or-nothing boundary. Name the trade rather than reciting a buzzword, because most organisations end up running both for years.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_vpn-protects_f2', 'q_network_fresher_vpn-protects', 2, 'Split tunnelling: good or bad?', 'It depends on what you give up. Split tunnelling saves bandwidth and keeps the concentrator alive, but it means the device''s general internet traffic never passes your inspection, so you lose that visibility. If the endpoint has its own telemetry you can live with it. If the VPN was your only visibility, you cannot.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_segmentation', 'network', 'segmentation', 'mid', 'You are asked to segment a flat corporate network. Where do you start?', 'With what talks to what, not with the diagram you wish you had. Collect flow data long enough to cover monthly jobs, group assets by function and sensitivity, then design the fewest zones that separate what must not reach each other. Enforce in monitor mode before you enforce for real.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_segmentation_f1', 'q_network_mid_segmentation', 1, 'Finance says segmentation will break their reporting tool.', 'Get the actual flows rather than the claim: source, destination, port, frequency. It is usually a handful you can allow explicitly. If the tool genuinely needs broad access, that becomes a documented exception with a compensating control and a named owner, not a reason to abandon the zone.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_segmentation_f2', 'q_network_mid_segmentation', 2, 'How do you prove the segmentation holds?', 'Test from inside each zone: attempt the connections that should fail and confirm they fail at the enforcement point, not just that nobody complained. Keep it as a repeatable check, because rule sprawl quietly re-flattens a network inside a year and nobody notices until an incident.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_dns-exfil', 'network', 'dns', 'mid', 'You see repeated TXT queries to a domain registered three days ago. What is your read?', 'That shape fits DNS tunnelling or beaconing: TXT carries more than A records, and a newly registered domain is a standard indicator. Look at query volume, subdomain entropy, how regular the timing is, and which host is asking. Clockwork intervals mean a process, not a person.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_dns-exfil_f1', 'q_network_mid_dns-exfil', 1, 'How do you tell exfiltration from a misconfigured tool?', 'Content and direction. Tunnelling shows long, high-entropy subdomain labels and sustained two-way volume; a misbehaving security or telemetry agent queries a vendor domain with predictable labels. Identifying the process on the host settles it faster than any amount of packet analysis.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_dns-exfil_f2', 'q_network_mid_dns-exfil', 2, 'What do you block, and what breaks if you are wrong?', 'Sinkhole that domain, not TXT records and not the resolver. If you are wrong you break one tool and hear about it in minutes, which is recoverable. Blocking at the resolver breaks name resolution for everyone, which is an outage you caused while chasing a maybe.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_egress-filtering', 'network', 'architecture', 'mid', 'Design egress filtering for an office of three hundred people. Where do you start and where do you stop?', 'Start by learning what actually leaves, then default-deny the protocols nobody should be using outbound directly, such as DNS to anything but your resolvers, SMTP, and arbitrary high ports. Force web traffic through a proxy you can see. Stop short of a full allowlist of destinations unless the business is one that can live with it.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_egress-filtering_f1', 'q_network_mid_egress-filtering', 1, 'Engineering says default-deny will break their builds hourly.', 'They are probably right, and that is an argument about sequencing, not direction. Run in log-only mode long enough to capture the real destination set, give them a documented path to request additions with a fast turnaround, and enforce per segment rather than everywhere at once. Enforcement without a working exception process always gets rolled back.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_egress-filtering_f2', 'q_network_mid_egress-filtering', 2, 'What does this actually buy you against a determined attacker?', 'Not prevention. It buys constraint and signal: it pushes them onto the few channels you watch closely, and it turns a silent exfiltration into a blocked connection that fires an alert. Claiming it stops a capable attacker is the answer that loses credibility in the room.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_lateral-movement', 'network', 'detection', 'mid', 'You cannot segment the network this quarter. How do you detect lateral movement anyway?', 'Watch for the behaviours segmentation would have blocked: workstation-to-workstation SMB or RDP, which almost never happens legitimately, authentication from one account across many hosts in a short window, and admin tools running where no admin works. Detection cannot replace segmentation, but it shortens the time you are blind.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_lateral-movement_f1', 'q_network_mid_lateral-movement', 1, 'Your IT team does exactly that all day with remote support tools.', 'Then baseline them and alert on the exception: the named support accounts from their jump hosts are normal, and the same behaviour from a finance laptop is not. The work is identifying the legitimate pattern precisely enough that everything outside it is interesting, which is most of the effort in any detection like this.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_lateral-movement_f2', 'q_network_mid_lateral-movement', 2, 'What is the single highest-value log source here?', 'Authentication, specifically where each account signs in and from what. Lateral movement is an identity story before it is a network story, and account-to-host mapping catches techniques that never generate distinctive network traffic at all.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_vpn-saturated', 'network', 'troubleshooting', 'mid', 'The VPN concentrator is saturated and people cannot work. Diagnose it.', 'Separate the three candidates before touching anything: more users than capacity, one user or process consuming the link, or the device itself degraded. Check concurrent sessions against the licensed and tested limit, top talkers by volume, and CPU on the box. Then say which it is rather than restarting and hoping.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_vpn-saturated_f1', 'q_network_mid_vpn-saturated', 1, 'It is one host pushing enormous volume. Is that an incident?', 'It might be a backup client, a sync tool, or exfiltration, and the destination tells you which in about a minute. Treat it as a performance issue until the destination says otherwise, but do look, because "the network was slow" is how a number of real exfiltrations were first noticed and then dismissed.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_vpn-saturated_f2', 'q_network_mid_vpn-saturated', 2, 'Leadership wants it fixed now. What do you do first?', 'Restore service with the least destructive lever: throttle or disconnect the one offending session rather than resetting the device and dropping three hundred people. Then say what the permanent fix is, capacity or split tunnelling or both, and what it costs. Fix now, design later, but do not let later never come.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_ports-on-a-web-server', 'network', 'ports', 'fresher', 'Which ports would you expect open on a normal web server, and which one open would make you look twice?', '80 and 443 for the site itself, and probably 22 for the admins, ideally not from the whole internet. The one that makes me look twice is something like 3389 or a database port exposed publicly: remote desktop or a database should not be reachable from outside, and finding them open usually means a mistake or a foothold someone left.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_ports-on-a-web-server_f1', 'q_network_fresher_ports-on-a-web-server', 1, 'You find 3389 open to the world on it. What do you do?', 'Treat it as an exposure first: get it firewalled to admin sources or behind a VPN, then check the logs for whether anyone has already been knocking, because an open RDP port on the internet is found by scanners within minutes.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_ports-on-a-web-server_f2', 'q_network_fresher_ports-on-a-web-server', 2, 'The team says it has been like that for a year with no problem. Does that reassure you?', 'No. No problem usually means no one has looked, not that no one has been in. A year of exposure is a year of opportunity, so I would want the authentication logs before I believe nothing happened.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_first-look-at-a-pcap', 'network', 'traffic-analysis', 'fresher', 'I hand you a packet capture and say something is wrong, with no other context. What do you look at first?', 'The shape before the detail: the protocol hierarchy to see what is actually in there, the conversations to see who is talking to whom and how much, and whether anything is on a port that does not match its protocol. I am looking for the odd one out, not reading every packet, because a capture is too big to read and the anomaly is usually in the summary.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_first-look-at-a-pcap_f1', 'q_network_fresher_first-look-at-a-pcap', 1, 'The protocol hierarchy shows a lot of DNS. Does that interest you?', 'It can. A lot of DNS, especially long or odd query names to one domain, is a classic tunnelling or beaconing pattern. I would look at the query names and the destination before deciding it is just a busy resolver.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_first-look-at-a-pcap_f2', 'q_network_fresher_first-look-at-a-pcap', 2, 'You spot credentials in cleartext. How bad, and what do you do?', 'Bad enough to act on: cleartext credentials on the wire mean anyone on the path has them. I note what protocol carried them, flag the application that should not be using it, and treat those credentials as compromised until rotated.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_proxy-beaconing', 'network', 'c2', 'fresher', 'A proxy log shows one host requesting the same URL every thirty seconds, each time a tiny response. Your read?', 'That regularity is the tell. Humans and normal apps are bursty; a request on a fixed interval with a small, consistent response looks like a beacon checking in with a controller. I would not conclude command-and-control from one pattern, but it earns a close look at the destination and the process making the calls.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_proxy-beaconing_f1', 'q_network_fresher_proxy-beaconing', 1, 'The destination is a well-known cloud provider''s domain. Does that clear it?', 'No. Attackers hide behind reputable infrastructure precisely because people wave it through. The domain being trusted does not change that the timing looks automated; I still want to know what on that host is calling it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_proxy-beaconing_f2', 'q_network_fresher_proxy-beaconing', 2, 'How would you confirm it is a beacon and not a legitimate poll?', 'Look at the jitter and the payloads over time: a legitimate poll usually varies and does real work, a beacon tends to be metronomic with near-identical tiny exchanges until it gets a task. And I would tie it to a process, because a legitimate poller is something you can name.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_arp-for-defenders', 'network', 'layer2', 'fresher', 'What is ARP, and why should a defender care about it?', 'ARP maps an IP address to a MAC address on a local network, so devices can actually deliver frames to each other. A defender cares because it has no authentication: a host can claim to be the gateway, and others will believe it. That is ARP spoofing, and it is how someone on the same LAN quietly puts themselves in the middle of traffic.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_arp-for-defenders_f1', 'q_network_fresher_arp-for-defenders', 1, 'How might you notice it happening?', 'A MAC address suddenly mapping to an IP it never did, two IPs sharing a MAC, or a gateway''s MAC changing. Switches and monitoring can flag it; on the wire it shows as a flurry of unsolicited ARP replies.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_arp-for-defenders_f2', 'q_network_fresher_arp-for-defenders', 2, 'It is the switch''s job to stop this, is it not?', 'Only if someone turned on the features: dynamic ARP inspection and DHCP snooping. Out of the box a flat LAN trusts ARP completely, so it is a configuration choice, not something you get for free.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_where-to-place-a-sensor', 'network', 'monitoring', 'mid', 'Where do you place a network sensor, and what do you miss at each spot?', 'At the perimeter you see what enters and leaves but nothing host-to-host inside; in the core or at distribution you see east-west movement but can drown in volume; at the host you see everything for that host and nothing else. There is no single right spot, so the honest answer is a mix and being clear about the blind spot each one leaves.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_where-to-place-a-sensor_f1', 'q_network_mid_where-to-place-a-sensor', 1, 'Most of your traffic is now encrypted. What does that do to the perimeter sensor?', 'It takes away the payload. You still get who-talks-to-whom, volumes, timing, and destinations, which is a lot, but you stop seeing content. That is why metadata and endpoint telemetry matter more as encryption spreads.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_where-to-place-a-sensor_f2', 'q_network_mid_where-to-place-a-sensor', 2, 'Given one sensor and a flat network, where do you put it?', 'At the egress point, because the thing I least want to miss is data leaving and hosts calling out to a controller. Internal movement matters, but a sensor that watches the door catches the step that turns an intrusion into a breach.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_decrypt-all-tls', 'network', 'tls-inspection', 'mid', 'The business wants to decrypt all TLS so it can be inspected. Walk me through the trade-offs.', 'You gain payload visibility, which is real. You also take on the risk of holding everyone''s decrypted traffic, you break anything that pins certificates or expects end-to-end trust, you create a privacy and legal question around personal and health and banking traffic, and you add latency and a single point of failure. It is a legitimate control, but it is a decision with costs, not a free upgrade.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_decrypt-all-tls_f1', 'q_network_mid_decrypt-all-tls', 1, 'What would you refuse to decrypt, and why?', 'Traffic to banking, health, and other sensitive or regulated destinations, and anything where interception crosses a legal or privacy line. The point of inspection is defence, not building a honeypot of your own staff''s private data.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_decrypt-all-tls_f2', 'q_network_mid_decrypt-all-tls', 2, 'Something breaks after you turn it on. Where do you look first?', 'Certificate pinning and applications that validate the chain themselves: mobile apps, updaters, and some APIs will refuse a middle certificate. The break is usually an app that was doing exactly what it was supposed to.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_unassigned-ip-on-the-network', 'network', 'rogue-device', 'mid', 'A device on the network has an IP you did not assign. How do you find it, and why do you care?', 'I care because an unknown device is unknown risk: it could be a staff member''s personal kit, a test box someone forgot, or something that should not be there at all. To find it I work from the IP to the MAC in the ARP or DHCP tables, then to the switch port it is plugged into, which gives me the physical location.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_unassigned-ip-on-the-network_f1', 'q_network_mid_unassigned-ip-on-the-network', 1, 'It turns out to be a personal router someone plugged in. Still a problem?', 'Yes. An unmanaged router can hand out its own addresses, bridge an untrusted network in, and create a path around your controls. Intent does not change the exposure, so it comes off the network and the policy gets a reminder.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_unassigned-ip-on-the-network_f2', 'q_network_mid_unassigned-ip-on-the-network', 2, 'How would you stop unknown devices getting on in the first place?', 'Network access control: require the port to authenticate the device before it gets anything but a quarantine network. Short of that, at least switch-port security and monitoring, so a new MAC is noticed rather than trusted.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_public-site-under-ddos', 'network', 'ddos', 'mid', 'Your public site looks like it is under a distributed denial-of-service. What can you actually do from the network side, and what can you not?', 'First I work out whether it is volumetric, filling the pipe, or application-layer, exhausting the server with valid-looking requests, because the answer is different. Against volume you cannot win locally: you need upstream help from the ISP or a scrubbing or CDN provider to absorb it before it reaches your link. Against application-layer you have more room with rate limiting, filtering, and caching. The hard truth is that if the pipe is full, nothing you do on your own side empties it.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_public-site-under-ddos_f1', 'q_network_mid_public-site-under-ddos', 1, 'The business asks why you cannot just block the attacking IPs. What do you tell them?', 'Because there are too many, they change, and some are spoofed, and because blocking them still means the traffic arrived at your link and filled it. Blocking helps at the edges, but it does not solve a volumetric flood that is already saturating the connection.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_public-site-under-ddos_f2', 'q_network_mid_public-site-under-ddos', 2, 'It eases off after an hour. Are you done?', 'No. An hour of denial of service is sometimes cover for something else, so I check whether anything happened while attention was elsewhere, and I treat the respite as a chance to get scrubbing in place before it comes back.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_which-osi-layer-attacks-live', 'network', 'fundamentals', 'fresher', 'The OSI model gets memorised. Which layer do most of the attacks you would actually see live at, and why?', 'Layer 7, the application layer, because that is where the data and the logic are and where the humans interact. Most of what a defender deals with day to day, phishing, web exploits, malware, is application-layer, not clever packet craft. The lower layers matter, but the model is most useful to me as a way to say which layer a given problem and its fix live at, not as a list to recite.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_which-osi-layer-attacks-live_f1', 'q_network_fresher_which-osi-layer-attacks-live', 1, 'Give me an attack that genuinely lives lower down.', 'ARP spoofing at layer 2 to get in the middle of a LAN, or a SYN flood at layer 4 exhausting connection state. They are real, but they need local access or volume, which is why they are less of the daily diet than a layer-7 phishing link.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_which-osi-layer-attacks-live_f2', 'q_network_fresher_which-osi-layer-attacks-live', 2, 'Why does knowing the layer actually help you respond?', 'Because it tells you where the control and the fix belong: a layer-7 problem is not solved by a layer-3 firewall rule. Naming the layer stops people reaching for the wrong tool, like trying to block an application flaw at the network edge.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_vlan-is-not-segmentation', 'network', 'segmentation', 'fresher', 'What is a VLAN, and why is ''we have VLANs'' not the same as ''we are segmented''?', 'A VLAN logically splits one physical switch into separate broadcast domains, so devices on different VLANs are not on the same local network. But VLANs only separate; segmentation is about controlling what is allowed to cross between them. If everything routes freely between your VLANs, you have tidy addressing and no security boundary, because the separation means nothing without rules enforcing it.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_vlan-is-not-segmentation_f1', 'q_network_fresher_vlan-is-not-segmentation', 1, 'So what turns VLANs into real segmentation?', 'Policy at the boundary: a firewall or access control between the VLANs that permits only the traffic that should cross and denies the rest. The VLAN is the line on the map; the enforcement is the fence. Without the fence, the line is decorative.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_vlan-is-not-segmentation_f2', 'q_network_fresher_vlan-is-not-segmentation', 2, 'How would you test whether two segments are actually separated?', 'Try to reach across: from a host in one segment, see what you can actually talk to in another, on which ports. If I can reach things I should not, the segmentation exists on the diagram and not in the traffic, which is the gap that matters.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_corporate-wifi-real-vs-theatre', 'network', 'wireless', 'fresher', 'What actually protects a corporate wireless network, and what is theatre?', 'Real protection is strong authentication, ideally per-user via enterprise authentication rather than one shared password, modern encryption, and treating wireless as untrusted so it does not drop straight onto the crown jewels. Theatre is hiding the network name and filtering by MAC address: the name is trivial to discover and MAC addresses are trivial to spoof, so both feel like security and stop nobody who is trying.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_corporate-wifi-real-vs-theatre_f1', 'q_network_fresher_corporate-wifi-real-vs-theatre', 1, 'Why is a single shared Wi-Fi password a problem at a company?', 'Because it never really leaves: ex-staff know it, it gets shared, and you cannot revoke one person without changing it for everyone. Per-user authentication means access is tied to an identity you can turn off, which is the whole point in an organisation.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_corporate-wifi-real-vs-theatre_f2', 'q_network_fresher_corporate-wifi-real-vs-theatre', 2, 'Where should corporate Wi-Fi sit in the network?', 'Behind the same controls as any other untrusted entry, not bridged straight into the internal network. Treat the person on Wi-Fi as outside until they authenticate to what they need, because the air does not have a wall around it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_fresher_lots-of-icmp', 'network', 'protocols', 'fresher', 'A host is sending a lot of ICMP. Innocent or not?', 'Usually innocent, sometimes not. ICMP is normal network plumbing, pings and path messages, so volume alone is not alarming. What interests me is shape: large or oddly sized ICMP payloads, a steady stream to one external host, or ICMP where it has no business being can be a covert channel or tunnel. So I do not panic at ICMP, I look at whether this ICMP is carrying more than it should.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_lots-of-icmp_f1', 'q_network_fresher_lots-of-icmp', 1, 'How would ICMP be used to smuggle data?', 'By stuffing payload into the data field of echo packets, which many networks pass without inspecting, so a host quietly tunnels traffic or exfiltrates in and out over ping. The tell is payload size and regularity that normal diagnostics would never produce.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_lots-of-icmp_f2', 'q_network_fresher_lots-of-icmp', 2, 'Would you just block ICMP to be safe?', 'Not blanket, because some of it is load-bearing: block the wrong type and you break path MTU discovery and troubleshooting. I would restrict and monitor it rather than kill it, because the cure of blocking all ICMP causes its own quiet outages.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_what-zero-trust-actually-changes', 'network', 'zero-trust', 'mid', 'Everyone says zero trust. What does it actually change about how you build a network?', 'It drops the idea that being inside the network means being trusted. Instead of a hard perimeter and a soft inside, every request is authenticated and authorised on its own merits, per user and per device, regardless of where it comes from. In practice that means identity becomes the real boundary, internal traffic is no longer trusted by default, and access is least-privilege and verified continuously rather than granted once at the door.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_what-zero-trust-actually-changes_f1', 'q_network_mid_what-zero-trust-actually-changes', 1, 'What is the most common way zero trust goes wrong in practice?', 'Buying a product and calling it done. Zero trust is an architecture and a discipline, not a box: if you still have a flat trusted internal network behind the shiny access gateway, you have the label and not the model.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_what-zero-trust-actually-changes_f2', 'q_network_mid_what-zero-trust-actually-changes', 2, 'Does zero trust mean the perimeter firewall is pointless now?', 'No, it means it is no longer sufficient. The firewall still reduces exposure and noise, but you stop treating everything behind it as safe. It is one layer, not the whole strategy, which is the shift zero trust is really making.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_netflow-but-no-pcap', 'network', 'forensics', 'mid', 'You have netflow but no packet capture. What can you still investigate, and what is lost?', 'Netflow gives me the who, when, how much and how long of every conversation: which hosts talked, on what ports, in which direction, and the volumes over time. That is enough to spot beaconing, exfiltration shapes, scanning, and lateral movement. What is lost is content: I cannot see what was actually said, read a payload, or pull the exact file, so I can say this host sent a lot to that one but not what was in it.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_netflow-but-no-pcap_f1', 'q_network_mid_netflow-but-no-pcap', 1, 'A host exfiltrated data and you only have netflow. What can you still say?', 'That it happened, when, to where, and roughly how much: the metadata tells the story of a transfer even without the contents. For scoping an incident that is often enough to act, even if I cannot show the exact bytes that left.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_netflow-but-no-pcap_f2', 'q_network_mid_netflow-but-no-pcap', 2, 'Given that gap, would you add full packet capture everywhere?', 'No, it is expensive and storage-hungry, so I would place it selectively at high-value choke points and lean on netflow and endpoint data for the breadth. Capturing everything everywhere is a cost and a privacy liability that rarely pays for itself.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_two-thousand-rule-base', 'network', 'firewall', 'mid', 'You are handed a firewall rulebase with two thousand rules. How do you find the dangerous ones?', 'I hunt for the rules that quietly undo everything else: any-to-any or any-service permits, overly broad source or destination ranges, rules allowing inbound from the internet to internal services, and anything with no owner or comment. Then the dead weight: shadowed rules never hit, expired temporary rules that became permanent, and duplicates. Two thousand rules is usually a dozen that are dangerous and a long tail of cruft.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_two-thousand-rule-base_f1', 'q_network_mid_two-thousand-rule-base', 1, 'What makes an ''any-any'' rule so bad in a long rulebase?', 'It silently overrides the careful rules around it: a broad permit near the top means the specific denies below it never get evaluated. One lazy rule can make the other nineteen hundred decorative, which is why I look for those first.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_two-thousand-rule-base_f2', 'q_network_mid_two-thousand-rule-base', 2, 'How do you safely remove a rule you think is dead?', 'Check the hit counters and logs to confirm it really takes no traffic, disable rather than delete first so it is reversible, and watch for fallout before removing it for good. A rule that looks dead but carries one critical flow at month-end is how a cleanup becomes an outage.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_network_mid_east-west-blind-spot', 'network', 'architecture', 'mid', 'Why is east-west traffic the blind spot everyone talks about, and what do you actually do about it?', 'Because the classic defences watch the perimeter, the north-south door, while most tools and sensors never see host-to-host traffic inside. Once an attacker is in, they move sideways through that unwatched space freely. What you do about it is bring visibility and control inside: segment so lateral paths are limited, instrument internal traffic so movement is logged, and stop assuming the inside is safe just because it is behind the firewall.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_east-west-blind-spot_f1', 'q_network_mid_east-west-blind-spot', 1, 'Microsegmentation is the usual answer. What is the catch?', 'Operational cost and complexity: done to the extreme it becomes a maze of policies nobody can maintain, and a policy you cannot maintain fails open. I would segment by real trust boundaries that match how the business works, not chase per-host purity that collapses under its own weight.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_east-west-blind-spot_f2', 'q_network_mid_east-west-blind-spot', 2, 'If you could only add one thing to see east-west, what would it be?', 'Logging of internal authentication and connections, because lateral movement is mostly made of logons and connections between hosts that do not normally talk. Even without full packet capture, that record turns an invisible sideways crawl into something you can follow.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_owasp-most-common', 'pentest', 'web', 'fresher', 'Which OWASP Top 10 risk do you see most often in real applications, and why that one?', 'Broken access control, because it is a logic problem rather than a pattern a scanner matches. Authentication comes from a framework; authorisation is written per endpoint by hand, so one missing ownership check in one route is enough. Answer with why it recurs, not just the name.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_owasp-most-common_f1', 'q_pentest_fresher_owasp-most-common', 1, 'Show me how you would test for it on a login-protected endpoint.', 'Authenticate as a low-privilege user, capture a request that references an object you own, then replay it with another identifier while keeping your own session. If someone else''s data comes back, that is the finding. Repeat for write operations, because read and write are often guarded differently.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_owasp-most-common_f2', 'q_pentest_fresher_owasp-most-common', 2, 'The developer says the WAF blocks it.', 'Demonstrate it through the WAF, from the path a real user takes. A WAF matches patterns; an authorisation flaw is a valid, well-formed request the application should have refused. If it still works end to end, the argument is settled without a debate.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_scan-vs-test', 'pentest', 'scope', 'fresher', 'What is the difference between a vulnerability scan and a penetration test?', 'A scan enumerates known issues against signatures and reports what might be exploitable. A test proves impact by chaining findings the way an attacker would. Put in client terms: a scan tells you what is present, a test tells you what it is worth.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_scan-vs-test_f1', 'q_pentest_fresher_scan-vs-test', 1, 'A client wants a pentest but the budget fits a scan. What do you tell them?', 'Say plainly that a scan will not answer the question they are asking, then offer the honest middle: a scan plus manual validation of the highest-impact findings, scoped to the part of the estate that carries real risk. Selling a scan as a test is how firms lose clients at the next breach.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_scan-vs-test_f2', 'q_pentest_fresher_scan-vs-test', 2, 'What goes in the report that a scanner cannot produce?', 'The chain and the consequence: how three mediums combined into access to a named dataset, what an attacker holds at the end, and what to fix first given their constraints. A scanner produces severity. A tester produces a prioritised story somebody can act on.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_sqli-confirm', 'pentest', 'web', 'fresher', 'What is SQL injection, and how would you confirm it on a live client system without breaking anything?', 'Untrusted input reaching a query as code rather than data. Confirm with the least invasive proof available: a boolean or timing difference that shows the query is being altered, not a payload that dumps or modifies data. On production you prove controllability and stop, then describe the impact rather than demonstrating it.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_sqli-confirm_f1', 'q_pentest_fresher_sqli-confirm', 1, 'Blind injection, no output at all. How do you prove it?', 'Inference. A conditional that changes the response, or a timing primitive that makes the server pause when a condition is true. Keep the proof small and reproducible, because a report that says "probably injectable" gets closed, and one with a repeatable condition does not.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_sqli-confirm_f2', 'q_pentest_fresher_sqli-confirm', 2, 'The fix they propose is escaping quotes. Is that enough?', 'No. Escaping is a filter and filters get bypassed through encoding, numeric contexts and places quoting does not apply, such as an ORDER BY clause. The fix is parameterised queries so input can never be parsed as code, with validation and least-privilege database accounts as depth, not as the fix.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_encode-hash-encrypt', 'pentest', 'crypto', 'fresher', 'Encoding, hashing and encryption: what is the difference and when is each the wrong choice?', 'Encoding changes representation and reverses with no secret, so it is not protection. Hashing is one way and is for verifying, not storing recoverable data. Encryption is reversible with a key and is for data you need back. The interview failure is calling base64 encryption, and the real-world failure is hashing something you later need to read.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_encode-hash-encrypt_f1', 'q_pentest_fresher_encode-hash-encrypt', 1, 'You find passwords stored as unsalted MD5. How bad, and what do you write?', 'Bad, and the reason is not that MD5 is "broken" in the abstract: it is fast and unsalted, so a commodity GPU plus a rainbow table recovers most of those passwords in minutes. Write it as credential compromise with reuse risk across other services, not as a cryptography nitpick.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_encode-hash-encrypt_f2', 'q_pentest_fresher_encode-hash-encrypt', 2, 'They ask what to use instead.', 'A slow, salted password hash designed for the job: Argon2id, scrypt or bcrypt, with parameters tuned to their hardware. Say that migration happens on next login rather than in a big bang, since you cannot reverse the old hashes. Give the migration path, because that is the part that stalls these fixes.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_default-creds', 'pentest', 'engagement', 'fresher', 'You find default credentials on an admin panel during an engagement. What now?', 'Confirm they work, capture the evidence, and stop. Do not start exploring with those credentials unless the scope explicitly permits it. Then judge the impact: what that panel controls decides whether this is a routine finding or a call you make today rather than at the readout.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_default-creds_f1', 'q_pentest_fresher_default-creds', 1, 'The panel manages their payment flow. Same handling?', 'No. That is an out-of-band notification the same day, through the escalation path agreed before the engagement started. You still do not go further in. The value you add is speed and clarity about what is exposed, not proving how far you could have gone.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_default-creds_f2', 'q_pentest_fresher_default-creds', 2, 'You log in and find someone else is already there.', 'Stop, preserve what you saw, change nothing, and escalate immediately as a live incident rather than a finding. Your own actions need to be clearly separable from theirs in their timeline, which is another reason to have been logging your own activity from the first minute.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_learning-changed', 'pentest', 'behavioural', 'fresher', 'What is the last thing you learned that changed how you test?', 'They are checking whether you actually practise or just collect certificates. Name something specific and recent, what you believed before, and what you do differently now. "I learned to read the application''s own authorisation code before testing it, because guessing object ids was wasting days" beats any list of tools.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_learning-changed_f1', 'q_pentest_fresher_learning-changed', 1, 'Where do you practise?', 'Be concrete and honest: labs, deliberately vulnerable applications, CTFs, your own builds, a bug bounty programme. Say what you did, not what you have an account on. Claiming bounty experience that turns into zero submissions is a short conversation and a memorable one.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_learning-changed_f2', 'q_pentest_fresher_learning-changed', 2, 'What are you bad at?', 'Answer it properly. Naming a real gap and what you are doing about it reads as someone who can be trusted on scope. A polished non-answer like "I care too much about quality" tells the interviewer you will also sound confident about findings you do not understand.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_shell-next', 'pentest', 'engagement', 'mid', 'You get a shell on a web server during an engagement. What do you do next?', 'Before anything else, confirm the host is in scope and record the time, the path in and what you ran, because that record is what makes the finding defensible. Then establish where you are: user context, host role, what it can reach. Collect what proves impact rather than expanding access for its own sake.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_shell-next_f1', 'q_pentest_mid_shell-next', 1, 'The scope says web application only.', 'Then you may already be at or past the boundary. Stop, document the access as the finding, and get written confirmation before touching the host further. Impact is already proven; carrying on without authorisation turns a strong finding into a contract problem.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_shell-next_f2', 'q_pentest_mid_shell-next', 2, 'You find evidence someone else was already in.', 'Stop testing and notify immediately through the agreed escalation path, because it is now a live incident rather than a test. Preserve what you saw and change nothing. Your activity log matters more than ever, because their responders need to separate you from the intruder.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_severity-call', 'pentest', 'reporting', 'mid', 'How do you decide what to report as critical?', 'Reachable impact, not CVSS alone. What does an attacker get, who can reach it, and what does pulling it off require. An unauthenticated path to customer data is critical; the same bug behind an admin login on an internal segment usually is not. State the reasoning so the rating can be argued with.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_severity-call_f1', 'q_pentest_mid_severity-call', 1, 'The client disagrees with your severity.', 'Ask what they know that you do not, because they often do: a compensating control, a boundary, data that is not what it looks like. If it changes the exposure, adjust and say why. If it does not, keep the rating and record their position in the report rather than quietly lowering it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_severity-call_f2', 'q_pentest_mid_severity-call', 2, 'What makes a finding actionable rather than just alarming?', 'A reproduction a developer can follow, the exact location in code or configuration, the fix stated in their stack rather than in general terms, and a way to verify it worked. Without those, a critical sits in a backlog for a year and everyone blames each other.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_undocumented-api', 'pentest', 'api', 'mid', 'You are handed an API with no documentation and two weeks. How do you approach it?', 'Build the surface map first: proxy the client application to enumerate real endpoints, look for a spec file or schema the app fetches, and check for predictable patterns and old versions left routable. Then establish the authorisation model, because that is where the findings are, and test object access systematically rather than endpoint by endpoint.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_undocumented-api_f1', 'q_pentest_mid_undocumented-api', 1, 'Where are the findings usually, in your experience?', 'Object-level authorisation and forgotten versions. The mobile client often talks to an older, looser endpoint that the web app no longer uses and nobody retired. Mass assignment is the other recurring one: fields the client never sends but the server will happily accept, such as a role or an account id.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_undocumented-api_f2', 'q_pentest_mid_undocumented-api', 2, 'Rate limiting blocks your enumeration. What do you do?', 'Tell the client and agree an allowance or a test window rather than quietly working around a control in production. Working around it can look identical to an attack in their logs, and it also means you never report that rate limiting worked, which was itself worth knowing.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_prod-testing', 'pentest', 'scope', 'mid', 'A client asks you to test production during business hours. What do you negotiate before saying yes?', 'A named contact reachable throughout, an agreed stop condition and who can call it, a window for anything with outage potential, confirmation that backups exist and have been tested, and what is explicitly out of bounds such as denial of service or destructive payloads. Get it in writing and timestamp your own activity.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_prod-testing_f1', 'q_pentest_mid_prod-testing', 1, 'Mid-test, a service goes down. Was it you?', 'Say what you were doing at that moment, immediately, whether or not you think you caused it. Hand over your activity log and help them rule you in or out fast. Going quiet to avoid blame is the single fastest way to lose a client, and it usually comes out anyway.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_prod-testing_f2', 'q_pentest_mid_prod-testing', 2, 'They refuse to give you a stop condition. Do you proceed?', 'Push once, explaining that the stop condition protects them more than you, and if it still is not forthcoming, record the refusal in writing and set a conservative one yourself. Testing production with nobody authorised to stop you is how a test becomes an incident with your name on it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_ad-approach', 'pentest', 'infrastructure', 'mid', 'Walk me through how you would approach an Active Directory environment.', 'Enumerate before you touch anything: users, groups, computers, trusts, delegation and service accounts, which is almost all readable by any authenticated user. Then look for the structural weaknesses rather than exploits: over-privileged service accounts, unconstrained delegation, Kerberoastable accounts with weak passwords, and paths to Domain Admin that nobody intended.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_ad-approach_f1', 'q_pentest_mid_ad-approach', 1, 'What do you check before running anything noisy?', 'Whether they have an EDR and whether the engagement is meant to be detected. If it is a purple exercise, noisy is the point and you coordinate. If it is a stealth test, you pace yourself and avoid the tooling their product signatures. Either way you agree it first rather than finding out from their SOC.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_ad-approach_f2', 'q_pentest_mid_ad-approach', 2, 'You get Domain Admin on day two. Now what?', 'Stop and report, rather than spending the rest of the engagement enjoying it. Then, with their agreement, use the remaining time on what actually helps: the paths that got you there, which of them are cheapest to cut, and what their detection did or did not see along the way.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_nothing-critical', 'pentest', 'reporting', 'mid', 'Two weeks, and you found nothing critical. What goes in the report?', 'What you tested, how, and what that coverage means, so "nothing critical" is a measured result rather than an absence of effort. Include the lower-severity findings honestly, note the controls that genuinely held and why, and name what you could not reach. A clean report with stated coverage is a legitimate and useful outcome.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_nothing-critical_f1', 'q_pentest_mid_nothing-critical', 1, 'The client says they paid for findings and feels short-changed.', 'Reframe what they bought: evidence about their security posture, not a guaranteed quota of bugs. Show the coverage, and point out that inflating mediums into highs to fill pages is exactly what makes reports useless. Then offer the harder follow-up, such as an assumed-breach scenario, which usually does find something.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_nothing-critical_f2', 'q_pentest_mid_nothing-critical', 2, 'Your colleague suggests upgrading a few mediums to look better.', 'No, and the reason is practical as well as ethical. Inflated severities train the client to ignore your ratings, so the real critical you find next year gets the same shrug. The value of the rating is that it is believed.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_what-recon-gets-you', 'pentest', 'recon', 'fresher', 'Before you touch anything, what does reconnaissance actually get you on an external engagement?', 'A map and some cheap findings. You learn the real attack surface, the technology in use, exposed services and old forgotten hosts, and often the people and the naming conventions that make later steps easier. Good recon means you spend the engagement testing the things that exist rather than guessing, and sometimes the win is already sitting in what you found.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_what-recon-gets-you_f1', 'q_pentest_fresher_what-recon-gets-you', 1, 'Give me a finding that recon alone can hand you.', 'An exposed service that should not be public, a forgotten staging site with weaker controls, leaked credentials in a code repository, or a subdomain pointing at a service that no longer exists and can be claimed. None of that needed an exploit, just looking carefully.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_what-recon-gets-you_f2', 'q_pentest_fresher_what-recon-gets-you', 2, 'How do you keep recon from tipping off the client''s defenders too early?', 'Favour passive sources first, public records and third-party data, before active scanning, and pace the active work. Whether being noisy matters depends on the engagement''s goals, so it is a scope conversation, not a default.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_explain-xss-to-a-dev', 'pentest', 'web', 'fresher', 'Explain cross-site scripting to me as if I am the developer who has to fix it, not as a slide.', 'Your page takes something a user controls and puts it into the page without neutralising it, so their input becomes script that runs in someone else''s browser, as your site. If it is stored, every visitor runs it; if it is reflected, a crafted link does. The fix is to encode output for the context it lands in and to use a content security policy, not to try to blocklist bad input, because you will never list it all.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_explain-xss-to-a-dev_f1', 'q_pentest_fresher_explain-xss-to-a-dev', 1, 'I already strip out the word script. Am I safe?', 'No. There are many ways to run code that never contain that word: event handlers, other tags, encoded forms. Blocklisting specific strings is a game you lose; encoding on output is the move because it neutralises whatever the input was.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_explain-xss-to-a-dev_f2', 'q_pentest_fresher_explain-xss-to-a-dev', 2, 'Where exactly do I encode, given I show the value in HTML and also in a bit of JavaScript?', 'In both, but differently: HTML-encode where it lands in the page body, and use the JavaScript-string context rules where it lands in script. The encoding has to match the context, which is why one blanket escape sometimes still leaves a hole.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_test-acting-as-someone-else', 'pentest', 'authorization', 'fresher', 'You can log in as yourself. How do you test whether you can act as someone else?', 'I look for places where the application trusts an identifier the client can change: an account or object id in a URL or body, a role or privilege carried in a token or a hidden field, a request that should check who you are but only checks that you are logged in. Then I change my id to someone else''s and see if the server lets me, which is the heart of broken access control.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_test-acting-as-someone-else_f1', 'q_pentest_fresher_test-acting-as-someone-else', 1, 'You change the id and get someone else''s invoice. Big deal or not?', 'Big deal. That is a direct object reference the server did not authorise: if one id works, all of them probably do, so it is not one leaked invoice, it is everyone''s, retrievable by counting. The impact is the whole dataset, not the one record.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_test-acting-as-someone-else_f2', 'q_pentest_fresher_test-acting-as-someone-else', 2, 'The developer says the id is a long random string, so it is fine. Convinced?', 'Less worried, more careful. A hard-to-guess id raises the bar but is not authorisation: if the string leaks in a log, a referrer, or a shared link, access is still granted. Unguessable is not the same as checked.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_ran-the-tool-found-nothing', 'pentest', 'methodology', 'fresher', 'A junior says they ran the scanner and it found nothing, so the target is secure. What is your response?', 'That the tool found nothing it knows how to find, which is not the same thing. Automated tools catch the known and the obvious; the findings that matter on real engagements are usually logic flaws, access-control gaps, and chained issues that no scanner understands. Empty output is a starting point, not a verdict.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_ran-the-tool-found-nothing_f1', 'q_pentest_fresher_ran-the-tool-found-nothing', 1, 'So what do you do that the scanner cannot?', 'Understand what the application is for and test the ways it can be abused: can I act as another user, skip a step, change a price, replay a request, reach something I should not. That reasoning about intent and flow is exactly what a signature-based tool has no model of.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_ran-the-tool-found-nothing_f2', 'q_pentest_fresher_ran-the-tool-found-nothing', 2, 'Is there any value in the scanner, then?', 'Yes, as a fast sweep of the known so I do not spend human time on the obvious. It clears the floor; it does not search the room. The mistake is treating the floor being clear as the room being empty.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_linux-privesc-first-checks', 'pentest', 'privilege-escalation', 'mid', 'You have a low-privilege shell on a Linux box. Walk me through getting higher, and what you check first.', 'I enumerate before I exploit, because the box usually tells you how it falls. First the easy wins: what can this user run with sudo, any SUID binaries that should not be there, writable files or scripts that run as root, cron jobs, and stored credentials. Only after that do I reach for a kernel exploit, which is the loud, fragile option, not the first one.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_linux-privesc-first-checks_f1', 'q_pentest_mid_linux-privesc-first-checks', 1, 'Why not go straight for a kernel exploit?', 'Because it is the riskiest move: it can crash the box, it is version-specific, and on a real engagement knocking over a production server is a bad day for everyone. A misconfiguration is quieter, more reliable, and far more common, so it is where I start.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_linux-privesc-first-checks_f2', 'q_pentest_mid_linux-privesc-first-checks', 2, 'sudo -l shows you can run one specific editor as root. Useful?', 'Very. Many ordinary programs can spawn a shell or write a file once they run as root, so a single allowed command is often a full escalation. The lesson for the defender is that a narrow sudo grant on the wrong binary is a wide-open door.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_dumped-hashes-how-bad', 'pentest', 'cryptography', 'mid', 'You dumped a set of password hashes. What determines whether that is a big deal or not?', 'The algorithm and how it was used. Modern, slow, salted hashes like bcrypt or argon2 resist cracking and a strong policy helps; fast or unsalted hashes like plain MD5 or NTLM fall quickly, and reused or weak passwords fall faster. The same dump can be a non-event or a full account takeover depending entirely on how the passwords were stored.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_dumped-hashes-how-bad_f1', 'q_pentest_mid_dumped-hashes-how-bad', 1, 'Why does salting matter so much?', 'Because without it, identical passwords produce identical hashes, so you crack once and unlock everyone who used that password, and precomputed tables do the work for you. A per-user salt forces the attacker to attack each hash separately, which is the whole point.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_dumped-hashes-how-bad_f2', 'q_pentest_mid_dumped-hashes-how-bad', 2, 'The hashes are bcrypt with a good work factor. Do you just move on?', 'Not entirely. Strong hashing buys time, not immunity: weak and reused passwords can still fall to a targeted guess, and the dump itself shows a database was reachable. I report the exposure and the real-world risk, not just bcrypt is fine.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_pivot-from-dmz-host', 'pentest', 'pivoting', 'mid', 'You have compromised a host in the DMZ with a route into the internal network. How do you reach further without getting caught?', 'Carefully and within scope. Technically I use the foothold to pivot, tunnelling or routing through it to reach internal systems I could not touch directly, and I prefer the tools already on the host over dropping my own, to stay quiet. But the real first question is whether reaching further is in scope and agreed, because the line between a thorough test and causing an incident is the engagement rules, not my curiosity.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_pivot-from-dmz-host_f1', 'q_pentest_mid_pivot-from-dmz-host', 1, 'What makes pivoting noisy, and how do you keep it quiet?', 'New tools on disk, unusual internal connections from a host that never makes them, and spikes of scanning. Quiet means living off what is there, moving at a human pace, and touching only what the objective needs rather than mapping the whole network loudly.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_pivot-from-dmz-host_f2', 'q_pentest_mid_pivot-from-dmz-host', 2, 'The scope is ambiguous about internal access. What do you do?', 'Stop and ask, in writing, before I cross the line. Reaching deeper than agreed is how a penetration test becomes a real incident and a legal problem, so an ambiguous scope is a conversation to have, not a gap to exploit.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_client-dismisses-your-finding', 'pentest', 'reporting', 'mid', 'Your critical finding is waved off by the client''s developers as not exploitable in practice. How do you handle it?', 'I separate my ego from the evidence and make the impact concrete: show the exploit path, the data or access it yields, and the conditions it needs, rather than arguing severity labels. If after a real demonstration they still choose to accept the risk, that is their call to make, but it gets written down as an accepted risk with an owner, not quietly dropped.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_client-dismisses-your-finding_f1', 'q_pentest_mid_client-dismisses-your-finding', 1, 'They still will not budge after the demo. Have you failed?', 'No. My job is to find and prove the risk clearly; the decision to fix or accept it is the business''s. A finding that is understood and formally accepted is a success of the process. What would be a failure is letting it vanish because someone was uncomfortable.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_client-dismisses-your-finding_f2', 'q_pentest_mid_client-dismisses-your-finding', 2, 'How do you tell a real not exploitable from a defensive brush-off?', 'By testing the claim. If they say a control blocks it, I try to show it does not, or I acknowledge it if it genuinely does. Real mitigations survive a demonstration; brush-offs are usually assertions that fold the moment you actually try the path.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_explain-csrf', 'pentest', 'web', 'fresher', 'Explain CSRF, and why ''I check the referrer header'' is not a great fix.', 'CSRF tricks a logged-in user''s browser into making a state-changing request they did not intend, riding on the cookies the browser sends automatically. So the server sees a valid, authenticated request that the user never meant to make. Checking the referrer is weak because it can be absent for privacy reasons, spoofable in some setups, and stripped by proxies, so you end up either blocking legitimate users or trusting a header you cannot rely on. The real fix is an anti-CSRF token the attacker cannot predict, or same-site cookies.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_explain-csrf_f1', 'q_pentest_fresher_explain-csrf', 1, 'Why does a token work where the referrer does not?', 'Because the token is a secret tied to the user''s session that the attacker''s forged request cannot know, so a request without the right token is rejected. The referrer is information the browser volunteers; the token is a secret only the real page has.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_explain-csrf_f2', 'q_pentest_fresher_explain-csrf', 2, 'Does being a JSON API instead of a form protect you from CSRF?', 'Partly and not reliably. It raises the bar because simple forms cannot set arbitrary content types, but misconfigured CORS or permissive endpoints can reopen it, so I would still test rather than assume the format saved me.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_app-lets-you-upload-files', 'pentest', 'web', 'fresher', 'An app lets users upload files. What is the first thing you try?', 'I test what it actually accepts versus what it claims to. Can I upload a file type it should reject, can I make a dangerous file look allowed by changing its name or declared type, and crucially what happens to it after, where does it land and can I reach it back. The prize is getting a file the server will execute, or one that becomes someone else''s problem when they open it, so I probe the gap between the client-side check and what the server really does.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_app-lets-you-upload-files_f1', 'q_pentest_fresher_app-lets-you-upload-files', 1, 'The app only checks the file extension. Why is that not enough?', 'Because the extension is just a label the client controls, so I rename a dangerous file to an allowed extension, or use a double extension or a trailing trick, and the content is still what it was. The server has to judge the file by what it is and where it can run, not by its name.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_app-lets-you-upload-files_f2', 'q_pentest_fresher_app-lets-you-upload-files', 2, 'You get a file uploaded but cannot execute it. Still useful?', 'Often yes. A file that others download and open is a path to attacking them, a malicious document or a script, and an upload that overwrites something or fills storage is its own problem. Execution is the jackpot, but an upload you control is leverage even without it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_port-445-open', 'pentest', 'services', 'fresher', 'You find port 445 open on a host. What does that tell you, and what do you try?', '445 is SMB, Windows file sharing, so this is almost certainly a Windows host offering shares or related services. That is interesting because SMB has a long history of exposure: anonymous or guest-readable shares, weak authentication, and famous exploitable bugs. So I would enumerate what shares and information it gives up without credentials first, then test authentication, because SMB often hands over more than people realise before you even log in.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_port-445-open_f1', 'q_pentest_fresher_port-445-open', 1, 'What is the risk of SMB being reachable from the internet specifically?', 'It is a high-value, heavily targeted service that should never face the internet: internet-exposed SMB is scanned constantly and has been the vector for major worms. Finding 445 open externally is itself close to a finding, before I test anything.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_port-445-open_f2', 'q_pentest_fresher_port-445-open', 2, 'You enumerate and find a readable share with no login. How bad?', 'Depends what is in it, and often it is bad: configuration files, credentials, backups, and internal data sit on shares people assume nobody can reach. Anonymous read access is a direct information-disclosure finding and frequently the first step to something larger.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_fresher_test-session-handling', 'pentest', 'web', 'fresher', 'How do you test whether an application handles sessions securely?', 'I look at the whole lifecycle of the session token. Is it long and random enough not to be guessed, is it sent and stored safely with the right cookie flags, does it change when you log in so a fixed one cannot be planted, and does it actually die on logout and after inactivity. The failures I am hunting are a predictable token, one that survives logout, or one an attacker can set for a victim in advance.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_test-session-handling_f1', 'q_pentest_fresher_test-session-handling', 1, 'Why does the token needing to change at login matter?', 'Because if it does not, an attacker can plant a known session token on a victim before they log in, and once the victim authenticates, the attacker already holds a now-valid session. Rotating the token at login closes that fixation path.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_test-session-handling_f2', 'q_pentest_fresher_test-session-handling', 2, 'You log out and the old token still works. How serious?', 'Serious: logout that does not actually invalidate the session server-side means a stolen or logged token stays usable after the user thinks they are safe. On a shared or compromised machine that is a direct account-takeover window.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_ssrf-in-cloud', 'pentest', 'web', 'mid', 'What is SSRF, and why is it so dangerous in cloud environments specifically?', 'Server-side request forgery is when you make the server itself make a request you choose, so it reaches things you cannot reach directly, internal services behind the firewall. In the cloud that is especially dangerous because the server can often reach the platform''s internal metadata service, which may hand out the instance''s credentials. So an SSRF that would be a nuisance on-prem can, in a cloud, turn into stealing the machine''s identity and pivoting into the whole account.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_ssrf-in-cloud_f1', 'q_pentest_mid_ssrf-in-cloud', 1, 'Walk me through how SSRF becomes credential theft in a cloud.', 'You find a feature that fetches a URL you control, point it at the internal metadata endpoint, and the server, trusted from inside, retrieves the instance''s temporary credentials and hands them back to you. Now you authenticate to the cloud as that instance, with whatever it was allowed to do.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_ssrf-in-cloud_f2', 'q_pentest_mid_ssrf-in-cloud', 2, 'How do defenders reduce the blast radius of this?', 'Lock down the metadata service to require the newer, harder-to-abuse access method, give instances the least privilege so stolen credentials are nearly worthless, and block outbound requests to internal ranges from app servers. The SSRF may still exist; the payoff is what you starve.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_what-wifi-test-is-for', 'pentest', 'wireless', 'mid', 'You are asked to test wireless. What are you actually testing for?', 'Whether the wireless is a way into the things that matter. That means the strength of its authentication and encryption, whether a rogue or evil-twin access point could harvest credentials or get users to connect, whether the guest and corporate networks are truly separated, and where the corporate wireless lands once you are on it. The point is not can I crack a password in a vacuum, it is does the air give an attacker a foothold into the network.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_what-wifi-test-is-for_f1', 'q_pentest_mid_what-wifi-test-is-for', 1, 'Why does an evil-twin access point matter if the real Wi-Fi is encrypted?', 'Because it attacks the human, not the crypto: a convincing fake network or captive portal gets users to connect or type credentials, and encryption on the real network does nothing about a user handing their password to a lookalike. It targets trust, which is the weaker link.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_what-wifi-test-is-for_f2', 'q_pentest_mid_what-wifi-test-is-for', 2, 'You crack onto the corporate Wi-Fi. What is the real test now?', 'What that access reaches: if being on Wi-Fi drops you into the internal network with broad access, that is the finding, not the cracked password. Well-designed wireless treats a connected device as untrusted until it authenticates to what it needs, so I test whether that holds.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_assumed-breach', 'pentest', 'methodology', 'mid', 'What is an assumed-breach test, and when is it more useful than starting from zero?', 'An assumed-breach test starts from the premise that an attacker is already inside, so instead of spending the engagement trying to get a foothold, you are handed one and test what happens next: how far can you move, what can you reach, would the defenders notice. It is more useful when the question that matters is not can we be breached, everyone can, but what happens when we are, which is where real damage and real detection gaps live.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_assumed-breach_f1', 'q_pentest_mid_assumed-breach', 1, 'Why would a mature company prefer this over a traditional external test?', 'Because they already know the perimeter is not perfect, and the expensive unknown is their internal resilience and detection. Assumed breach spends the budget on the part that actually determines how bad an incident gets, rather than re-proving that initial access is possible.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_assumed-breach_f2', 'q_pentest_mid_assumed-breach', 2, 'Does assumed breach let the external defences off the hook?', 'It can if it is the only test you ever do, so it complements rather than replaces perimeter testing. The honest programme does both: can they get in, and when they do, how far do they get and who notices.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_pentest_mid_making-a-retest-worthwhile', 'pentest', 'reporting', 'mid', 'A client fixed your findings and wants a retest. How do you approach it so it is actually worth something?', 'I verify the fix, not the ticket. For each finding I re-test the actual exploit path to confirm it is genuinely closed, not just that a setting changed, and I check they fixed the class of issue rather than the one instance I happened to report. A retest that just reads their remediation notes and marks things green is theatre; the value is in trying the attack again and failing.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_making-a-retest-worthwhile_f1', 'q_pentest_mid_making-a-retest-worthwhile', 1, 'They fixed the exact URL you reported but not the others like it. Pass or fail?', 'Fail, or at least a partial: if the same flaw exists elsewhere because they patched the symptom I named rather than the cause, the risk is still live. I report that they fixed the instance and missed the class, because an attacker will not stop at the one URL I happened to list.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_making-a-retest-worthwhile_f2', 'q_pentest_mid_making-a-retest-worthwhile', 2, 'A fix introduced a new problem. Is that in scope for a retest?', 'Yes, I would raise it. A retest that only looks at the old findings and ignores a hole the fix just opened gives false comfort. The honest answer is whether the system is safer now, not whether the original list is ticked.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_shared-responsibility', 'cloud', 'fundamentals', 'fresher', 'Explain the shared responsibility model.', 'The provider secures the infrastructure the service runs on; the customer secures what they put in it and how they configure it. The line moves by service type, with managed services taking more of the stack, but identity, access and data configuration stay with the customer in every model.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_shared-responsibility_f1', 'q_cloud_fresher_shared-responsibility', 1, 'Who is responsible for a storage bucket left public?', 'The customer. The provider supplies the controls and increasingly defaults them to private, but the configuration is the customer''s. Nearly every public-bucket incident is a decision somebody made, not a provider failure.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_shared-responsibility_f2', 'q_cloud_fresher_shared-responsibility', 2, 'Name two things people assume the provider handles but it does not.', 'Backups and retention for managed data stores, which are usually opt-in and the customer''s to configure and actually test. And logging: control-plane and data-plane logs often need enabling and paying for, and if nobody turned them on there is no investigation after an incident.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_public-bucket', 'cloud', 'storage', 'fresher', 'A storage bucket is publicly readable. Walk me through the fix.', 'Establish exposure first: what is in it, for how long, and whether access logs show reads from outside. Then remove public access at the account level rather than object by object. Only after that work out how it happened, because the same mechanism has usually produced others you have not found yet.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_public-bucket_f1', 'q_cloud_fresher_public-bucket', 1, 'It serves a static website that genuinely must stay public.', 'Separate what must be public from what must not: one bucket holding only published assets, everything else moved out. Serve it through a CDN with the origin locked to the CDN rather than exposing the bucket, and keep account-level blocks on every other bucket.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_public-bucket_f2', 'q_cloud_fresher_public-bucket', 2, 'How do you stop the next one?', 'Enforcement, not a reminder: account-level public access blocks, a policy that refuses to create public buckets, and a check in the pipeline so it fails before it ships. Then alert on changes to that configuration, because a control is only as good as the notice you get when someone turns it off.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_iam-basics', 'cloud', 'iam', 'fresher', 'What is cloud IAM, and how is it different from a username and a password?', 'It is policy-based authorisation over every API call, for people and for workloads. The difference is granularity and reach: a policy says which identity may take which action on which resource under which conditions, and machines get identities too. A control-plane permission can be far more dangerous than a login, because it rewrites the environment.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_iam-basics_f1', 'q_cloud_fresher_iam-basics', 1, 'Which is more dangerous, a leaked user password or a leaked access key?', 'Usually the key. It carries whatever the identity can do, it works from anywhere without a browser, it does not prompt for a second factor, and keys rarely expire. A password often sits behind MFA and conditional access, while a key quietly works until somebody revokes it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_iam-basics_f2', 'q_cloud_fresher_iam-basics', 2, 'What does an identity policy not protect you from?', 'Anything done with legitimate permissions, which is most of what goes wrong. A correctly scoped identity used by the wrong person looks exactly like normal activity, which is why least privilege narrows the blast radius but logging and anomaly detection are what notice.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_security-groups', 'cloud', 'network', 'fresher', 'What does a cloud security group actually do, and what does it not?', 'It is a stateful virtual firewall attached to an instance or interface, allowing traffic by port, protocol and source. It does not inspect content, it does not stop anything already running on the host, and on most platforms it cannot express a deny rule, only an absence of allow.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_security-groups_f1', 'q_cloud_fresher_security-groups', 1, 'You find one with 0.0.0.0/0 on port 22. Is that always a finding?', 'Practically always, but check before calling it, because the fix depends on why. Sometimes it is a jump host nobody cleaned up after; sometimes a real administrative path that should be going through a bastion or a managed session service. The finding is the open path, the recommendation depends on the reason.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_security-groups_f2', 'q_cloud_fresher_security-groups', 2, 'They say it is fine because the instance has no public IP.', 'Then verify it, because that changes the exposure. A rule that is broad but unreachable is lower priority, not a non-issue: the next change that attaches a public address or a load balancer makes it live, with nobody re-reading the rule. Narrow it anyway and say why.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_first-three-cloud', 'cloud', 'strategy', 'fresher', 'A company is moving to cloud. Name the three things you would secure first, and defend the order.', 'Identity, then logging, then network exposure. Identity because the control plane is the new perimeter and a compromised admin identity is total loss. Logging second because without it you cannot investigate anything, including whether the first item already failed. Exposure third because it is the one you can keep fixing after the fact.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_first-three-cloud_f1', 'q_cloud_fresher_first-three-cloud', 1, 'Why logging before fixing open ports?', 'Because a missing control can be closed next week, but a missing log is gone for good. Turn on control-plane logging on day one and you can reconstruct what happened during the messy migration. Leave it until later and the whole early period is permanently unexaminable.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_first-three-cloud_f2', 'q_cloud_fresher_first-three-cloud', 2, 'Leadership says that is too slow. What do you drop?', 'Nothing on that list, but you can shrink it: MFA on privileged identities rather than a full identity redesign, logging on at default settings rather than a tuned pipeline, and public exposure only on internet-facing accounts. Offer a smaller version with a date rather than agreeing to skip a layer.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_secrets-handling', 'cloud', 'secrets', 'mid', 'How do you handle secrets in a cloud application?', 'In a managed secret store, injected at runtime, never in the repository, the image, or environment variables baked at build. Access scoped by identity, reads logged, rotation automated. Where the platform supports workload identity, use it and delete the long-lived credential entirely, because the best secret is the one that does not exist.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_secrets-handling_f1', 'q_cloud_mid_secrets-handling', 1, 'A developer committed a key to a public repository. What is your first hour?', 'Rotate first, investigate second. Revoke immediately, because removing the commit does not remove it from forks, caches or anyone who scraped it within seconds. Then pull the audit log for everything that key did from the moment it was pushed. The repository history and the conversation with the developer come after.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_secrets-handling_f2', 'q_cloud_mid_secrets-handling', 2, 'How do you know it was not used before you rotated?', 'The audit log filtered by that credential, from push to revocation: unfamiliar addresses, unusual regions, enumeration patterns, changes to identity or logging configuration. If logging was not on for that service, say so plainly. You cannot prove a negative, and the honest answer is that you do not know.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_wildcard-iam', 'cloud', 'iam', 'mid', 'An IAM role has wildcard permissions. How do you fix it without breaking production?', 'Do not guess a replacement policy. Determine what the role actually uses from access logs over a period long enough to include monthly jobs, build least privilege from observed calls, then run it in a mode that reports denials before enforcing. Narrow in stages, not in one change at the end of a sprint.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_wildcard-iam_f1', 'q_cloud_mid_wildcard-iam', 1, 'Nobody knows what the role uses. How do you find out?', 'Query the control-plane audit log for calls made by that role, grouped by service and action, over at least a full reporting cycle. Most providers also expose last-accessed data per service, which hands you the unused surface immediately. Use both: one shows what is used, the other shows what safely is not.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_wildcard-iam_f2', 'q_cloud_mid_wildcard-iam', 2, 'How do you stop it drifting back to wildcards?', 'Policy as code with review, an organisation-level guardrail that refuses wildcard actions on sensitive services, and an alert on policy changes. Drift happens at 2am during an outage, so the control has to be a refusal at deploy time rather than a quarterly audit that finds it months later.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_cloud-incident', 'cloud', 'incident-response', 'mid', 'You suspect a compromise in a cloud account. How is the investigation different from an on-premises one?', 'The control plane is both the crime scene and the toolkit. Your primary evidence is the API audit log rather than disk, and the attacker''s most valuable moves are configuration changes: new identities, new keys, policy edits, logging disabled. You can also snapshot and isolate instantly, which is a real advantage if you use it before you start poking.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_cloud-incident_f1', 'q_cloud_mid_cloud-incident', 1, 'What do you preserve first, and how?', 'The audit log, exported out of the account to somewhere the attacker''s identity cannot reach, because an attacker with control-plane access can stop or delete logging. Then snapshot affected volumes and capture instance metadata. Preservation comes before eradication: rebuilding first destroys the only account of what happened.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_cloud-incident_f2', 'q_cloud_mid_cloud-incident', 2, 'The attacker created a new access key on an existing role. What else do you check?', 'Everything that key touched, and then everything else they may have planted: other new keys and identities, trust policy edits that let an outside account assume a role, new regions suddenly in use, and changes to logging or alerting. Revoking one key and declaring victory is the standard mistake.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_container-root', 'cloud', 'containers', 'mid', 'A container is running as root. How bad is it, and what do you do?', 'On its own it is a weakness, not a breach: root in the container is not root on the host unless something else gives way. It matters because it removes a layer, so a code execution bug becomes a much better position, and it combines badly with a privileged flag, a mounted socket or a host path. Judge it with what is next to it.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_container-root_f1', 'q_cloud_mid_container-root', 1, 'It also mounts the container runtime socket. Now how bad?', 'Now it is effectively host compromise, because that socket lets you start a new container with the host filesystem mounted. That combination is one of the most reliable escapes there is. This stops being a hardening item and becomes something you fix this week, with the nodes it ran on treated as suspect.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_container-root_f2', 'q_cloud_mid_container-root', 2, 'The team says the image will not run as non-root.', 'Usually it is file ownership or a low port, and both have standard fixes: adjust ownership in the build, or bind higher and map the port. Ask them to show what fails rather than accepting the claim. If it genuinely cannot change, it needs isolation, a user namespace and a documented exception, not a shrug.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_secure-cicd', 'cloud', 'pipeline', 'mid', 'How do you secure a CI/CD pipeline, and why is it worth the effort?', 'Because the pipeline deploys to production, so compromising it beats compromising production. Secure it as a production system: short-lived credentials from workload identity rather than stored keys, no secrets in logs, pinned third-party actions, review required on the pipeline definition itself, and separate credentials per environment.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_secure-cicd_f1', 'q_cloud_mid_secure-cicd', 1, 'What is the most commonly missed one?', 'The pipeline definition being editable by anyone who can push, which means a branch can rewrite how production is deployed. The other is a workflow that runs on pull requests from forks with access to real secrets, which hands credentials to anyone on the internet who opens a PR.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_secure-cicd_f2', 'q_cloud_mid_secure-cicd', 2, 'How would you detect a compromised pipeline?', 'Alert on the pipeline''s own identity doing something outside its pattern: deploying from an unusual branch, touching resources it never touches, or running at an odd hour. Also watch for edits to the pipeline definition outside the normal review path. The build identity is usually highly privileged and almost never monitored.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_first-logging-service', 'cloud', 'logging', 'fresher', 'What is the one logging service you turn on first in a new cloud account, and why?', 'The account''s audit trail, the service that records who did what: every API call, who made it, from where, and whether it succeeded. I turn it on first because without it you are blind to your own account, and after an incident it is the difference between reconstructing what happened and guessing. It is also the thing attackers try to turn off.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_first-logging-service_f1', 'q_cloud_fresher_first-logging-service', 1, 'An attacker disables it. How would you know?', 'The act of disabling it is itself a logged event, right up until it stops, so the last entry is a tell. That is why the logs should be delivered somewhere the account being watched cannot reach, so turning them off locally does not erase the trail.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_first-logging-service_f2', 'q_cloud_fresher_first-logging-service', 2, 'Logging everything gets expensive. How do you decide what to keep?', 'Keep the management-plane trail, who-did-what, essentially forever and cheaply in cold storage, and be selective about high-volume data-plane logs. The audit trail is small and priceless; the per-object access logs are large and you keep what you would actually investigate.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_leaked-access-key', 'cloud', 'incident', 'fresher', 'A developer pasted a cloud access key into a public code repository. Walk me through the next hour.', 'Rotate and revoke the key first, before anything else, because it is public and bots scrape for exactly this within minutes. Then work out what that key could do, how over-privileged it was, and pull the audit log to see whether it was already used and for what. Removing it from the repository is last and almost beside the point, since it is already copied.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_leaked-access-key_f1', 'q_cloud_fresher_leaked-access-key', 1, 'You revoke it and the audit log shows it was used from an unknown IP ten minutes ago. Now what?', 'It is an incident, not a near miss. I scope what that key touched in those ten minutes, assume anything it could reach is compromised, and widen from there: new resources, new keys, changed permissions. The key being dead now does not undo what it did while alive.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_leaked-access-key_f2', 'q_cloud_fresher_leaked-access-key', 2, 'How do you stop the next one reaching the repo at all?', 'Secret scanning on commits so a key is caught before it lands, short-lived credentials instead of long-lived keys, and making the easy path the safe one so developers are not tempted to paste a static key in the first place.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_lock-down-root-account', 'cloud', 'iam', 'fresher', 'The root or owner account of a cloud organisation: what do you lock down on day one?', 'Hardware or app multi-factor on it, no daily use so it is reserved for the few things only it can do, no access keys attached to it, and alerting whenever it is used at all. The root account can undo every other control, so it is the one account where a compromise is total, and it should be boring and rarely touched.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_lock-down-root-account_f1', 'q_cloud_fresher_lock-down-root-account', 1, 'Why does it matter that root has no access keys?', 'Because an access key is a long-lived credential that can be leaked, and on the root account that is catastrophic. A human logging in with MFA for a rare task is defensible; a static all-powerful key sitting in a config somewhere is not.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_lock-down-root-account_f2', 'q_cloud_fresher_lock-down-root-account', 2, 'You get an alert that root just logged in. What is your first question?', 'Was it us? I want to know who, from where, and for what planned task, because a legitimate root login is a scheduled, announced, rare event. An unexplained one is treated as a compromise until proven otherwise.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_public-disk-snapshot', 'cloud', 'storage', 'fresher', 'A disk snapshot is shared publicly. Why does that matter more than it sounds?', 'Because a snapshot is a copy of a whole disk: the operating system, the application, and whatever secrets, keys, and data were on it at the moment it was taken. A public snapshot is not a misconfigured setting, it is a data breach waiting for someone to mount it, and people do scan for them.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_public-disk-snapshot_f1', 'q_cloud_fresher_public-disk-snapshot', 1, 'How is this worse than a public storage bucket?', 'A bucket exposes the objects someone put in it; a disk snapshot exposes everything, including the things nobody meant to be data: credentials in config files, tokens in memory dumps, private keys. The blast radius is the whole machine, not a folder.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_public-disk-snapshot_f2', 'q_cloud_fresher_public-disk-snapshot', 2, 'You make it private again. Is the incident over?', 'No. If it was public you have to assume it was copied, so you rotate every credential that was on that disk and investigate what the exposed data could unlock. Making it private stops new access; it does not recall what already left.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_cloud-privesc', 'cloud', 'privilege-escalation', 'mid', 'In the cloud, how does an attacker turn a low-privilege foothold into admin, and how would you spot it?', 'Usually through the identity layer, not an exploit: a role that can pass a more privileged role to a service, attach a policy to itself, create access keys for another identity, or update a function that already runs with high permissions. You spot it in the audit trail, where these are all logged API calls that look wrong for the identity making them, like a low-privilege user suddenly editing IAM.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_cloud-privesc_f1', 'q_cloud_mid_cloud-privesc', 1, 'Which single permission would worry you most to hand out loosely?', 'The ability to modify IAM itself, such as attaching policies or passing roles. It is the master key: anything that can change permissions can grant itself everything, so it is the one I watch and scope hardest.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_cloud-privesc_f2', 'q_cloud_mid_cloud-privesc', 2, 'Your detection is only the audit log. Is that enough here?', 'For this it is strong, because cloud privilege escalation is made of API calls and the log records them. The gap is speed: the log tells you after the fact, so the value is in alerting on the dangerous calls in near real time, not reading it next week.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_find-everything-internet-facing', 'cloud', 'exposure', 'mid', 'How do you find everything in a cloud account that is reachable from the internet?', 'Not by looking at one thing: public IPs on instances, load balancers, storage buckets and their policies, managed databases with public access, API gateways, and functions with public URLs. It is an inventory problem more than a scanning problem, because the account can expose things in a dozen ways, and the one you forget is the one that bites.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_find-everything-internet-facing_f1', 'q_cloud_mid_find-everything-internet-facing', 1, 'Why not just run an external port scan and call it done?', 'A scan finds open ports on IPs you point it at, but it misses the managed services with their own endpoints, the buckets that are not ports at all, and anything that spun up after you scanned. The cloud exposes things a port scan never sees.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_find-everything-internet-facing_f2', 'q_cloud_mid_find-everything-internet-facing', 2, 'How do you keep this current as the account changes daily?', 'Make it continuous, not a one-off: query the provider''s own inventory and configuration data on a schedule and alert on new public exposure. In a cloud that changes by the hour, a quarterly audit is a snapshot of a thing that has already moved.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_why-many-cloud-accounts', 'cloud', 'architecture', 'mid', 'Why do mature organisations use many cloud accounts instead of one big one, from a security view?', 'To bound the blast radius. If production, development, and each team live in separate accounts, a compromise or a mistake in one does not reach the others, permissions stay scoped, and billing and ownership are clear. The cost is complexity: more to manage, and you need a way to govern them centrally, so it is a trade of simplicity for containment.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_why-many-cloud-accounts_f1', 'q_cloud_mid_why-many-cloud-accounts', 1, 'What is the risk of getting the central governance wrong?', 'You recreate the single big account through the back door: one over-powerful management account or role that can reach into all the others. If that is compromised, separation buys you nothing, so the governing layer is the thing you protect hardest.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_why-many-cloud-accounts_f2', 'q_cloud_mid_why-many-cloud-accounts', 2, 'A small startup with one account asks if they are doing it wrong. Your answer?', 'No, not yet. Many accounts earns its complexity at scale; for a small team one well-run account with clear separation inside it is fine. The mistake is copying a big company''s structure before you have the size or the people to run it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_serverless-security-shift', 'cloud', 'serverless', 'mid', 'What changes about security when the application is serverless functions instead of servers?', 'You stop patching hosts, which is a real win, but the risk moves to the identity and the glue: each function has its own permissions that are easy to over-grant, functions are triggered by events that can be poisoned, and your dependencies and third-party packages become a larger part of your attack surface. You trade operating-system patching for permission hygiene and supply-chain care.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_serverless-security-shift_f1', 'q_cloud_mid_serverless-security-shift', 1, 'Where do over-permissioned functions come from, and why do they matter?', 'From copying a broad policy because it was easy and it worked. They matter because a compromised function inherits its permissions, so a function that only needed to read one bucket but was granted the account becomes a full foothold.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_serverless-security-shift_f2', 'q_cloud_mid_serverless-security-shift', 2, 'What is event injection in this world?', 'Trusting the trigger. A function fired by a file upload, a queue message, or an HTTP call is processing attacker-influenced input, and if it treats that input as trusted, the same injection problems you had on servers come back through the event instead of a form.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_why-region-matters', 'cloud', 'compliance', 'fresher', 'Why does the region a cloud resource lives in matter for security and compliance?', 'Because where the data physically sits decides which laws apply to it, who can compel access to it, and often what your own customers are contractually promised. A bucket in the wrong region can breach a data-residency requirement without anyone attacking anything. Latency and availability matter too, but the security answer is that geography is jurisdiction, and jurisdiction is not a setting you can hand-wave.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_why-region-matters_f1', 'q_cloud_fresher_why-region-matters', 1, 'A developer spins a database up in a region you do not use. Is that a problem?', 'Potentially a compliance one, even with no breach: it may put regulated data outside where it is allowed to live, and it is unmanaged shadow infrastructure nobody is watching. The fix is guardrails that restrict which regions can be used, not catching it after the fact.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_why-region-matters_f2', 'q_cloud_fresher_why-region-matters', 2, 'How do you stop resources being created in the wrong region at all?', 'Policy at the account level that denies resource creation outside approved regions, so it is prevented rather than discovered later. Relying on people to remember the rule is how the one-off exception becomes a permanent liability.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_encrypted-at-rest-protects-what', 'cloud', 'encryption', 'fresher', '''The data is encrypted at rest.'' What does that actually protect you from, and what does it not?', 'It protects against someone who gets the raw storage: a stolen disk, a leaked snapshot, a provider employee with physical access. It does not protect against someone who comes through the front door with valid access, because to the application and anyone with permission the data is transparently decrypted. Encryption at rest answers what if someone steals the drive, not what if someone steals the credentials.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_encrypted-at-rest-protects-what_f1', 'q_cloud_fresher_encrypted-at-rest-protects-what', 1, 'So if an attacker has the app''s database credentials, does encryption at rest help?', 'No. They are asking the system that holds the keys, and it hands back plaintext as designed. At-rest encryption is invisible to an authorised query, so against stolen credentials the control that matters is access, not encryption.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_encrypted-at-rest-protects-what_f2', 'q_cloud_fresher_encrypted-at-rest-protects-what', 2, 'When does encryption at rest genuinely save you, then?', 'When the storage layer leaks on its own: a public snapshot, a decommissioned disk, a backup that walks out. In those cases the bytes are useless without the key, which is exactly the threat it is built for.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_instance-has-a-public-ip', 'cloud', 'exposure', 'fresher', 'An instance has a public IP. Is that a problem?', 'Not by itself, but it is a question worth asking. A public IP means reachable from the internet, so the real question is what is listening and how well it is defended: a hardened, patched web server is meant to be public, a database or an admin service is not. So I do not treat a public IP as a verdict, I treat it as a prompt to check what it exposes and whether it should.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_instance-has-a-public-ip_f1', 'q_cloud_fresher_instance-has-a-public-ip', 1, 'How do you decide whether this one is fine or a risk?', 'Look at what ports are open to the world, what is behind them, and whether that service is designed to face the internet. A public IP on a web tier is normal; the same on a management port is the finding.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_instance-has-a-public-ip_f2', 'q_cloud_fresher_instance-has-a-public-ip', 2, 'The developer says they need it public to work from home. Better way?', 'Put the access behind something that authenticates first, a VPN or a bastion or an identity-aware proxy, rather than exposing the service itself. The need is remote access, and remote access does not require the whole service to sit open on the internet.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_fresher_why-tagging-matters', 'cloud', 'governance', 'fresher', 'Why do security people care about resource tagging?', 'Because you cannot protect what you cannot find or attribute. Tags are how you know who owns a resource, what it is for, how sensitive it is, and whether it is in scope for a given control. In an environment that changes by the hour, untagged resources are the ones that get forgotten, left exposed, and discovered only in an incident. Tagging is unglamorous, but it is the backbone of knowing your own estate.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_why-tagging-matters_f1', 'q_cloud_fresher_why-tagging-matters', 1, 'Give me a security decision that depends on a tag.', 'Who to call when a resource is compromised at 3am: an owner tag turns a mystery instance into a phone call. Or whether a bucket is allowed to hold regulated data, driven by a data-classification tag that a policy can enforce against.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_why-tagging-matters_f2', 'q_cloud_fresher_why-tagging-matters', 2, 'Tags are optional, so people skip them. How do you fix that?', 'Make them non-optional where it counts: deny creation of resources without the required tags, so the estate stays attributable by construction. A tagging standard that relies on goodwill decays the moment someone is in a hurry.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_stop-self-escalation', 'cloud', 'iam', 'mid', 'How do you stop a team from granting themselves more cloud permissions than they should?', 'By putting a ceiling above them that they cannot raise: a permission boundary or equivalent that caps what any identity in their scope can do, so even an admin within the team cannot exceed it. Combine that with separating who can change permissions from who uses them, and with alerting on identity-policy changes. The principle is that the power to grant access is itself a privilege, held above the people it governs.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_stop-self-escalation_f1', 'q_cloud_mid_stop-self-escalation', 1, 'Why is ''just trust the team leads'' not enough here?', 'Because it is one compromised or mistaken account away from unlimited: if the people with access can also expand their own access, there is no real ceiling, only a polite agreement. A boundary enforced by the platform does not depend on everyone behaving.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_stop-self-escalation_f2', 'q_cloud_mid_stop-self-escalation', 2, 'How would you catch an attempt to escalate, boundary or not?', 'Alert on the dangerous identity actions: attaching policies, creating keys for others, assuming more privileged roles. Those are logged API calls, so a low-privileged identity suddenly editing permissions is a signal you can fire on in near real time.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_vpc-peering-expanded-what', 'cloud', 'networking', 'mid', 'Two cloud networks are peered. Security-wise, what did you just expand?', 'The blast radius. Peering makes the two networks mutually reachable, so a compromise on either side now has a path to the other that it did not before. It is not transitive and it is not automatic access, but it is a new trust relationship, and the question I ask is what can now reach what, and is that limited to the few things that actually need to talk, or did you just merge two networks in effect.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_vpc-peering-expanded-what_f1', 'q_cloud_mid_vpc-peering-expanded-what', 1, 'So what makes a peering safe rather than a liability?', 'Scoping it: route and security rules that allow only the specific flows that need to cross, not blanket reachability. A peering with wide-open rules quietly turns two blast radii into one; a tightly scoped one connects just the two services that had to.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_vpc-peering-expanded-what_f2', 'q_cloud_mid_vpc-peering-expanded-what', 2, 'A third network is peered to one of these two. Can it reach the other?', 'Not through the peering itself, because peering is not transitive: it only connects the two directly peered networks. But people often add routes or gateways that create a path anyway, so I would check the actual routing, not assume the non-transitive rule saved me.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_four-hundred-packages', 'cloud', 'supply-chain', 'mid', 'Your cloud app pulls four hundred open-source packages. How do you think about that risk?', 'As a trust problem I cannot eliminate, only manage. Every one of those packages, and their dependencies, is code I did not write running with my app''s privileges, so a malicious or compromised one is a foothold. I think about it as: know what I actually depend on, pin and verify versions, watch for known vulnerabilities and sudden maintainer changes, and reduce the count where I can. The goal is not zero dependencies, it is not being surprised by them.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_four-hundred-packages_f1', 'q_cloud_mid_four-hundred-packages', 1, 'What is the specific danger of a dependency''s dependency?', 'That you never chose it and may not know it is there, yet it runs with the same trust. Most of the four hundred are transitive, pulled in by something you did pick, so the risk hides a layer below the names in your own manifest.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_four-hundred-packages_f2', 'q_cloud_mid_four-hundred-packages', 2, 'A popular package you use ships a malicious update. How would you even catch it?', 'By not blindly taking latest: pin versions, review changes before upgrading, and watch for the signals, a new maintainer, an unexpected release, odd new network behaviour at build or run time. The defence is that an update is a change you vet, not something that flows in automatically.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_cloud_mid_cloud-backups-vs-ransomware', 'cloud', 'resilience', 'mid', 'How do cloud backups survive ransomware, and how do they not?', 'They survive it when they are genuinely out of reach of the thing that got compromised: a separate account or isolation boundary, immutable so they cannot be altered or deleted for a set period, and with their own access path. They do not survive when the same credentials that run production can also reach and delete the backups, because then the attacker encrypts the originals and wipes the copies in one move. A backup your attacker can delete is not a backup.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_cloud-backups-vs-ransomware_f1', 'q_cloud_mid_cloud-backups-vs-ransomware', 1, 'Why is immutability the feature that matters most here?', 'Because ransomware''s move against backups is deletion or encryption, and immutability makes the data un-deletable and un-alterable for its retention window regardless of credentials. It takes the backups off the table even for an attacker holding admin.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_cloud-backups-vs-ransomware_f2', 'q_cloud_mid_cloud-backups-vs-ransomware', 2, 'You have backups but never tried restoring. What is the risk?', 'That they do not actually work when you need them: wrong scope, corrupt, missing a dependency, or so slow the business is down for days anyway. An untested backup is a hope, not a control, so the restore has to be rehearsed before the bad day, not during it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_policy-standard-procedure', 'grc', 'documents', 'fresher', 'What is the difference between a policy, a standard and a procedure?', 'A policy states intent and is approved by leadership. A standard makes it measurable: the specific requirement a thing must meet. A procedure is the steps someone follows to meet it. Policies change rarely, standards change with technology, procedures change with tooling.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_policy-standard-procedure_f1', 'q_grc_fresher_policy-standard-procedure', 1, 'An auditor asks for evidence that a policy is followed. What do you show?', 'Not the policy. Output from the control: configuration exports, ticket records, access review sign-offs, log samples spanning the audit period. Evidence is what the system produced while nobody was watching, not a document describing what ought to happen.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_policy-standard-procedure_f2', 'q_grc_fresher_policy-standard-procedure', 2, 'The evidence does not exist.', 'Say so, rather than assembling it afterwards, which is how a finding becomes a fraud problem. Record it as a gap, start generating the evidence now, and give a remediation date. Auditors handle known gaps with a plan every day. They handle fabricated evidence very differently.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_risk-register', 'grc', 'risk', 'fresher', 'What does a risk register do, and what makes a bad one?', 'It records the risks the organisation has decided to track, each with an owner, a rating, a treatment decision and a review date. A bad one is a list of vulnerabilities with no owner, no decision and no date, which makes it an inventory nobody acts on rather than a tool for allocating attention.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_risk-register_f1', 'q_grc_fresher_risk-register', 1, 'A risk has been "in progress" for two years.', 'Treat the status as false and force a decision. Either it is genuinely being treated, in which case it needs a plan with dates, or the organisation has accepted it, in which case say so explicitly with a named accepting owner. A permanent in-progress entry is an unmade decision hiding as work.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_risk-register_f2', 'q_grc_fresher_risk-register', 2, 'Who should own a risk, security or the business?', 'The function that carries the consequence, because they are the ones who can accept it or fund the fix. Security owns the assessment, the recommendation and the follow-up. When security owns the risk itself, acceptance becomes invisible and nothing ever competes with revenue for budget.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_dpdp-basics', 'grc', 'privacy', 'fresher', 'What is India''s Digital Personal Data Protection Act, and who does it apply to?', 'It governs the processing of digital personal data of people in India, and it reaches organisations outside India that process such data to offer goods or services here. It works on consent and stated purpose, puts duties on the data fiduciary to secure data and report breaches, and gives people rights over their own data. Be clear it is principles and duties, not a technical checklist.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_dpdp-basics_f1', 'q_grc_fresher_dpdp-basics', 1, 'Your company collects phone numbers for delivery updates and later uses them for marketing. Any problem?', 'Yes. Consent is tied to a stated purpose, so a new purpose needs fresh consent rather than a clause buried in the original notice. The practical fix is separating consent at collection and holding a record of what was agreed to and when, because the record is what you have to produce later.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_dpdp-basics_f2', 'q_grc_fresher_dpdp-basics', 2, 'How is that different from GDPR in practice?', 'Same direction, different detail, and the honest answer says you would check the text rather than assuming equivalence. The shapes differ on lawful bases, on how children''s data is handled, and on the regulator and penalty structure. A team that assumes their GDPR programme covers DPDP ends up with gaps it never looked for.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_audit-vs-assessment', 'grc', 'assurance', 'fresher', 'What is the difference between an audit and an assessment?', 'An audit tests against a defined standard and produces a formal opinion, usually by an independent party, with evidence requirements and consequences. An assessment is advisory: it tells you where you stand and what to improve, with no pass or fail. Confusing them in front of a client is a quick way to lose credibility.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_audit-vs-assessment_f1', 'q_grc_fresher_audit-vs-assessment', 1, 'Internal audit asks you to help them prepare for an external audit. Any issue?', 'It depends how far it goes. Helping them understand requirements and find evidence is normal. Writing the evidence they will then test, or testing your own work, destroys the independence the audit exists for. Name the line and say who should do which part.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_audit-vs-assessment_f2', 'q_grc_fresher_audit-vs-assessment', 2, 'The external auditor raises a finding you disagree with.', 'Ask what evidence and what clause it rests on, because often it is a scoping misunderstanding you can clear up with one document. If it stands, accept it and fix it. If it genuinely does not, there is a management response process for exactly this. Arguing informally and leaving it unrecorded helps nobody.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_least-privilege-practice', 'grc', 'controls', 'fresher', 'What does least privilege mean in practice, not in theory?', 'That access is granted for a defined need, scoped to it, and removed when the need ends. The practical work is the removal: joiners get access easily everywhere, movers accumulate it, and leavers get missed. A programme that only controls granting is not doing least privilege, it is doing paperwork at the front door.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_least-privilege-practice_f1', 'q_grc_fresher_least-privilege-practice', 1, 'How would you find out whether it is actually happening?', 'Sample. Take ten people who changed roles in the last year and check whether their old access went away. Take five leavers and check every system, not just the directory. The gap between the policy and that sample is the real state, and it is usually a surprise to leadership.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_least-privilege-practice_f2', 'q_grc_fresher_least-privilege-practice', 2, 'Access reviews come back fully approved every quarter. Believable?', 'No. A review where managers approve everything in one click is a signature, not a control. The fix is making the review smaller and more specific, showing what the access actually permits in plain terms, and requiring a reason for keeping anything unused for ninety days.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_owner-refuses', 'grc', 'behavioural', 'fresher', 'A business owner refuses a control you have recommended. What do you do?', 'Find out why, because the reason is usually cost, timing or a workflow you did not know about, and all three are negotiable. Offer a smaller version or a compensating control. If they still refuse, write it up as an accepted risk with their name on it and a review date. Then move on without sulking.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_owner-refuses_f1', 'q_grc_fresher_owner-refuses', 1, 'They refuse to sign the acceptance too.', 'Then escalate, calmly and in writing, to whoever owns the risk above them. Unsigned acceptance is not refusal of the control, it is refusal of accountability for it, and that is a different and more serious problem. Record what was recommended, what was declined, and when you escalated.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_owner-refuses_f2', 'q_grc_fresher_owner-refuses', 2, 'Six months later it causes an incident. How do you handle the conversation?', 'Without a told-you-so, which buys nothing and costs the relationship you need for the next control. Produce the record, keep the focus on fixing it now, and let the decision trail speak. The organisations that learn from this are the ones where raising it was not treated as blame.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_iso-six-months', 'grc', 'certification', 'mid', 'You are asked to get the company ISO 27001 certified in six months. What is your first move?', 'Define the scope, because everything follows from it: which entity, which locations, which systems, which data. Then run a gap assessment against the controls in that scope, which usually finds more already happening in practice but undocumented than leadership expects.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_iso-six-months_f1', 'q_grc_mid_iso-six-months', 1, 'Leadership wants certification without changing how teams work.', 'Say plainly that certification audits evidence of operating controls, so if nothing changes there is nothing to evidence. Then make it tractable: scope tightly to the part of the business that needs the certificate commercially, rather than diluting controls across the whole company to keep everyone comfortable.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_iso-six-months_f2', 'q_grc_mid_iso-six-months', 2, 'Where do first-time certifications actually fail?', 'Not on the controls, on the management system. Risk assessment done once and never revisited, internal audit that did not happen, management review with no record, corrective actions left open. Those are the clauses auditors check first and the ones teams dismiss as paperwork.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_third-party-risk', 'grc', 'vendors', 'mid', 'How do you run third-party risk assessment that is not just a questionnaire nobody reads?', 'Tier vendors by what they can actually reach: data, network access, business criticality. Spend the effort on the top tier and let the long tail be light. Ask for evidence rather than self-attestation where it matters, and put the answers into the contract, because a questionnaire with no contractual teeth changes nothing.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_third-party-risk_f1', 'q_grc_mid_third-party-risk', 1, 'A critical vendor refuses to share their audit report.', 'Find out whether it is confidentiality or absence, because those are different problems. Confidentiality is solvable with an NDA or a summary. If the report does not exist, that is the finding, and the decision moves up to whoever is willing to accept depending on that vendor without assurance.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_third-party-risk_f2', 'q_grc_mid_third-party-risk', 2, 'What do you do between assessments?', 'Watch for the things that change without telling you: breach disclosures, ownership changes, certificate lapses, and your own usage growing past what was assessed. Annual assessment with nothing in between means your view of a vendor is on average six months out of date.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_after-breach', 'grc', 'regulatory', 'mid', 'Your company has had a breach. What does the regulator ask for, and what will you wish you had?', 'What happened, when you knew, what data and how many people, what you did, and how you are preventing recurrence. What you will wish you had is a timeline supported by evidence rather than recollection, and proof that your controls were operating before the incident, not just documented.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_after-breach_f1', 'q_grc_mid_after-breach', 1, 'Your detection timeline has a four-day gap nobody can explain.', 'Report the gap as a gap. An honest unexplained window is survivable; a confident timeline that later turns out to be wrong is not, because it recasts everything else you said as unreliable. Say what you know, what you cannot establish, and why.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_after-breach_f2', 'q_grc_mid_after-breach', 2, 'Legal wants to delay notification while the investigation continues.', 'There is a real tension and it is not yours to resolve alone, but notification clocks generally start on becoming aware, not on finishing the investigation. Your job is to make sure the decision is made knowingly, with the deadline and the facts in front of the people accountable, and recorded.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_measure-programme', 'grc', 'metrics', 'mid', 'How do you measure whether a security programme is actually working?', 'Pick measures tied to outcomes and to how fast you respond, not to activity. Time to detect and time to contain, coverage of critical assets by the controls that matter, how long high findings stay open, and how much of your estate you can actually see. Counting blocked attacks or training completions measures effort, not effect.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_measure-programme_f1', 'q_grc_mid_measure-programme', 1, 'The board wants a single number.', 'Give them three at most, with a trend and a plain sentence each, and refuse the single score politely. A composite number hides the thing that is getting worse inside the thing that is getting better, and the first time it does that in public it stops being believed.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_measure-programme_f2', 'q_grc_mid_measure-programme', 2, 'A metric is improving but you do not believe it.', 'Check what behaviour it created, because people optimise what is measured. Mean time to close drops beautifully when tickets get closed without fixing anything. Validate against the underlying reality by sampling, and change the measure if it has started rewarding the wrong move.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_soc2-vs-iso', 'grc', 'certification', 'mid', 'Explain SOC 2 and ISO 27001 to a CFO who wants to know which one to pay for.', 'ISO 27001 certifies a management system against an international standard and travels well, especially in Europe and Asia. SOC 2 is an attestation report by an auditor on how your controls operated, and North American customers ask for it by name. The CFO question is not which is better, it is which one your buyers are asking for.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_soc2-vs-iso_f1', 'q_grc_mid_soc2-vs-iso', 1, 'They ask whether doing one makes the other cheap.', 'Cheaper, not cheap. A lot of the underlying evidence overlaps, so the second costs noticeably less than the first, but the framing, scope and auditor work differ. Give them a rough ratio and say it depends on how well the first was scoped, rather than promising a number you will have to walk back.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_soc2-vs-iso_f2', 'q_grc_mid_soc2-vs-iso', 2, 'They ask whether either means you cannot be breached.', 'No, and say it directly. Both tell a customer that you run a managed programme and that an independent party checked it. Neither is a guarantee, and a certified company can still be breached. Overselling this is how security loses the room the first time something goes wrong.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_cia-real-tradeoff', 'grc', 'fundamentals', 'fresher', 'The CIA triad gets recited a lot. Give me a real decision where confidentiality and availability actually pulled against each other.', 'Locking an account after failed logins: it protects confidentiality by stopping a guesser, and it harms availability because a real user, or an attacker spraying known usernames, can lock people out. Or encryption where the only key holder leaves and the data is now safe and also unrecoverable. The triad is not a slogan, it is a set of trade-offs you have to actually choose between.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_cia-real-tradeoff_f1', 'q_grc_fresher_cia-real-tradeoff', 1, 'How do you make that lockout decision, then?', 'By the context: how sensitive the account is, how likely an attack is, and what being locked out costs. A banking admin and a public forum get different answers, which is the point, the right control depends on what you are protecting and from whom.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_cia-real-tradeoff_f2', 'q_grc_fresher_cia-real-tradeoff', 2, 'Is one of the three ever simply more important?', 'Depends entirely on the business. For a hospital system, availability can be life-or-death; for a secrets vault, confidentiality wins. Anyone who says one always leads has not had to make the trade with real consequences.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_control-types-stolen-laptop', 'grc', 'controls', 'fresher', 'Preventive, detective, corrective: give me one real control of each for a stolen laptop, and which you would fund first.', 'Preventive is full-disk encryption, so the thief gets a brick. Detective is an alert when the device checks in from somewhere new or is reported missing. Corrective is a remote wipe and re-issue. I fund encryption first, because detection and response after a loss are cold comfort if the data was readable the moment it left the building.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_control-types-stolen-laptop_f1', 'q_grc_fresher_control-types-stolen-laptop', 1, 'Why not fund detection first, so you at least know?', 'Because knowing a readable laptop is gone does not protect the data on it; it just tells you the breach already happened. Prevention changes the outcome, detection changes only your awareness of it, so for a loss you cannot undo, prevention earns the first rupee.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_control-types-stolen-laptop_f2', 'q_grc_fresher_control-types-stolen-laptop', 2, 'The laptop was encrypted but the password was on a sticky note on it. Now what?', 'Then the control did not operate, which is the whole lesson: a control on paper is not a control in practice. It becomes an awareness and enforcement problem, and in a report I would record it as a control that existed but failed to operate, which is different from one that was missing.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_compliance-vs-risk', 'grc', 'risk', 'fresher', 'A control is required by a standard but makes no sense for your actual risk. What do you do?', 'I do not just ignore it, and I do not blindly implement theatre either. I document why it does not fit, put a compensating control in place if the underlying intent still matters, and record a risk acceptance with an owner if it genuinely does not apply. Compliance and security are not the same thing, but you manage the gap openly rather than pretending it is not there.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_compliance-vs-risk_f1', 'q_grc_fresher_compliance-vs-risk', 1, 'The auditor will not accept your compensating control. Then what?', 'Then it becomes a business decision with the cost on the table: implement the required control anyway for the certification, or accept not having that certification. My job is to make the trade-off and its cost visible, not to quietly fail the audit or quietly fake the control.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_compliance-vs-risk_f2', 'q_grc_fresher_compliance-vs-risk', 2, 'Where is the line between pragmatism and just dodging controls?', 'Writing it down. A documented, owned, reasoned deviation is risk management; an undocumented one you hope nobody notices is negligence. The control you skipped is only defensible if you can show the thinking and someone signed for it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_what-counts-as-evidence', 'grc', 'assurance', 'fresher', 'An auditor asks for evidence that a control works. What counts, and what does not?', 'What counts is proof it actually operated: logs showing it ran, tickets showing it was followed, configurations showing it is set, samples over a period rather than one lucky day. What does not count is the policy that says it should happen. The difference an auditor is testing is between saying you do something and showing that you did.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_what-counts-as-evidence_f1', 'q_grc_fresher_what-counts-as-evidence', 1, 'You have the policy but no records that anyone followed it. What does that tell the auditor?', 'That the control exists on paper and may not exist in practice, which is often worse than having no policy, because it shows the organisation knows what it should do and is not doing it. A policy with no evidence is a finding, not a defence.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_what-counts-as-evidence_f2', 'q_grc_fresher_what-counts-as-evidence', 2, 'The control ran, but only because you knew the audit was coming. Honest evidence?', 'No. A control that operates only when watched is not operating; it is a performance. Honest assurance samples across normal time, and if it only works under observation, the real finding is that it does not work.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_risk-in-money-to-the-board', 'grc', 'risk', 'mid', 'The board asks how much cyber risk you have, in money. How do you answer honestly?', 'In ranges with stated assumptions, not a single confident figure. I would frame it as likelihood times impact across the scenarios that actually threaten us, show the big drivers, and be explicit about what is estimated. A precise-sounding number invented to satisfy the question is worse than an honest range, because the board will treat false precision as fact and plan around it.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_risk-in-money-to-the-board_f1', 'q_grc_mid_risk-in-money-to-the-board', 1, 'The board wants one number, not a range. How do you handle that?', 'I give a central estimate and immediately show the range around it, because the spread is the information. Collapsing it to one number hides the uncertainty that should drive how much they spend, so I answer the question without pretending the uncertainty is not there.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_risk-in-money-to-the-board_f2', 'q_grc_mid_risk-in-money-to-the-board', 2, 'Is this quantification worth doing if it is all estimates?', 'Yes, if it is honest, because it turns vague fear into a comparable number that can be weighed against the cost of fixing it. The value is in the relative comparison and the conversation, not in the decimal places, and good estimation beats no estimation and beats fake precision.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_who-declares-a-breach', 'grc', 'incident', 'mid', 'Who decides when an incident becomes a breach that must be reported, and why does that matter?', 'It should be decided by defined criteria and a named owner agreed before anything happens, not argued out in the heat of the moment. It matters because reporting obligations come with clocks and legal exposure, and the decision is easier to get wrong, or to delay, exactly when everyone is stressed. Deciding who calls it and on what basis is itself a control.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_who-declares-a-breach_f1', 'q_grc_mid_who-declares-a-breach', 1, 'Why is deciding this in advance so important?', 'Because in the middle of an incident there is pressure to downplay, and the regulatory clock may already be running. A criterion written in calm beats a judgement made in panic, and it protects the person who has to make the call from having to invent the rule under fire.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_who-declares-a-breach_f2', 'q_grc_mid_who-declares-a-breach', 2, 'Who should own that decision?', 'Someone with the authority and the context to act, usually a defined incident lead with legal and leadership in the loop, named ahead of time. What you want to avoid is everyone assuming someone else is making the call while the clock runs out.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_critical-vendor-wont-comply', 'grc', 'vendors', 'mid', 'A critical vendor will not meet your security requirements, but the business needs them. What is your actual move?', 'I treat it as risk management, not a gate. I understand exactly what the vendor touches and what could go wrong, then reach for compensating controls on our side, contract terms that put obligations and liability in writing, and monitoring of the connection. If residual risk remains, it gets accepted explicitly by someone senior enough to own it. A flat no the business overrules anyway protects nobody.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_critical-vendor-wont-comply_f1', 'q_grc_mid_critical-vendor-wont-comply', 1, 'Is there a point where you do say no?', 'When the residual risk after everything you can do is still unacceptable and the owner will not accept it in writing. The no has to be defensible and specific, tied to what cannot be mitigated, not a reflex because a questionnaire came back short.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_critical-vendor-wont-comply_f2', 'q_grc_mid_critical-vendor-wont-comply', 2, 'What is wrong with just refusing the vendor outright?', 'The business often needs them anyway and will go around you, which leaves the risk in place and you out of the loop. Engaging to reduce and own the risk keeps you in the decision; refusing on principle gets you ignored and the risk unmanaged.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_awareness-training-doesnt-work', 'grc', 'awareness', 'mid', 'Security awareness training mostly does not change behaviour. What would you do differently?', 'Stop measuring completion and start measuring behaviour: phishing-report and click rates, not slides watched. Make it targeted and role-based so finance hears about invoice fraud and developers hear about secrets, keep it short and frequent rather than an annual marathon, and most of all make the secure path the easy one, because people route around friction no matter how much they were trained.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_awareness-training-doesnt-work_f1', 'q_grc_mid_awareness-training-doesnt-work', 1, 'Give me an example of making the secure path the easy one.', 'A one-click report-phishing button that actually gets a response, or a password manager provided and set up so a strong unique password is less effort than reuse. When doing it right is easier than doing it wrong, behaviour changes without a lecture.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_awareness-training-doesnt-work_f2', 'q_grc_mid_awareness-training-doesnt-work', 2, 'How would you prove your programme is working?', 'By movement in the behaviours over time: report rates up, click rates down, repeat offenders shrinking, and real reports arriving early. Those are outcomes; completion percentages are activity, and activity is not the same as a workforce that actually catches things.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_gap-analysis-vs-audit', 'grc', 'assurance', 'fresher', 'What is a gap analysis, and how is it different from an audit?', 'A gap analysis is you honestly measuring yourself against a standard to find where you fall short, so you know what to fix before anyone formal shows up. An audit is someone, often independent, formally testing whether you meet the requirement and recording the verdict. The difference is purpose and teeth: a gap analysis is a private to-do list you own; an audit is an external judgement you answer to. You do the first so the second goes well.', 1, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_gap-analysis-vs-audit_f1', 'q_grc_fresher_gap-analysis-vs-audit', 1, 'Can the same person do both?', 'They can do a gap analysis, but a credible audit, especially a certification one, needs independence: you cannot objectively grade your own homework and have anyone trust the mark. For internal improvement, self-assessment is fine; for assurance to others, the separation is the point.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_gap-analysis-vs-audit_f2', 'q_grc_fresher_gap-analysis-vs-audit', 2, 'A gap analysis finds forty gaps. What do you do first?', 'Rank them by risk, not by how easy they are to close: fix what actually exposes you most, not what is quickest to tick. Forty gaps sorted by convenience is how the important ones stay open while the trivial ones get the attention.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_data-classification-why-it-fails', 'grc', 'data', 'fresher', 'Why does data classification matter, and why do most schemes fail?', 'It matters because you cannot apply the right protection to everything equally, so you have to know what is sensitive to spend effort where it counts. Most schemes fail because they are too complicated for people to use: five tiers with fuzzy definitions mean nobody classifies consistently, everything gets marked low to avoid friction or high to be safe, and the labels stop meaning anything. A classification scheme lives or dies on whether an ordinary employee can apply it without thinking hard.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_data-classification-why-it-fails_f1', 'q_grc_fresher_data-classification-why-it-fails', 1, 'So what does a scheme that actually works look like?', 'Few levels, clear examples, and defaults that make the easy path the right one. Three tiers people can tell apart beats five they cannot, because a scheme is only as good as the consistency of the humans applying it a hundred times a day.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_data-classification-why-it-fails_f2', 'q_grc_fresher_data-classification-why-it-fails', 2, 'Why is ''classify everything as confidential to be safe'' a problem?', 'Because if everything is sensitive, nothing is: you cannot prioritise protection, costs balloon, and people start ignoring the label because it is on things that plainly do not need it. Over-classification quietly destroys the signal the scheme exists to create.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_bcp-vs-dr', 'grc', 'resilience', 'fresher', 'Business continuity versus disaster recovery: what is the difference, with an example?', 'Business continuity is the whole plan for keeping the business running through a disruption; disaster recovery is the narrower, usually technical, piece about restoring systems and data. If a flood takes out your office, disaster recovery is getting the servers and data back online; business continuity is how staff keep serving customers meanwhile, from where, with what manual workarounds. DR is a subset: recovering IT is necessary but not the same as keeping the business alive.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_bcp-vs-dr_f1', 'q_grc_fresher_bcp-vs-dr', 1, 'A company has a great DR plan but no BCP. What breaks?', 'They can restore the systems but have not worked out how people actually operate in the meantime, where staff go, how they take orders, who talks to customers, so the technology comes back to a business that seized up around it. Recovered servers do not help if nobody planned how the humans keep working.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_bcp-vs-dr_f2', 'q_grc_fresher_bcp-vs-dr', 2, 'What two numbers anchor a DR plan, and what do they mean?', 'Recovery time objective, how fast you must be back, and recovery point objective, how much data you can afford to lose measured in time. Together they say be running again within X and lose no more than Y of data, and they drive what the recovery has to be capable of.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_fresher_what-makes-consent-valid', 'grc', 'privacy', 'fresher', 'Under a privacy law like India''s DPDP, what makes consent actually valid?', 'Consent has to be a real, informed, freely given yes to a specific purpose, not a default you have to hunt to switch off. That means telling the person plainly what you will do with their data and why, in language they understand, asking for it rather than assuming it, tying it to defined purposes rather than everything forever, and letting them withdraw it as easily as they gave it. Consent buried in a wall of text or pre-ticked is not consent, it is a liability.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_what-makes-consent-valid_f1', 'q_grc_fresher_what-makes-consent-valid', 1, 'A pre-ticked ''I agree'' box: valid consent?', 'No. Consent has to be an affirmative act by the person, so a box they must untick is the opposite, agreement assumed rather than given. It fails the freely-given and the clear-action test at once.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_what-makes-consent-valid_f2', 'q_grc_fresher_what-makes-consent-valid', 2, 'Someone withdraws consent. What has to happen?', 'You have to be able to act on it: stop the processing that relied on that consent and make withdrawal as easy as granting was. If your systems cannot actually find and stop using that person''s data, the right to withdraw is only words, and that gap is itself the finding.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_turning-risk-appetite-into-something-usable', 'grc', 'risk', 'mid', 'What is risk appetite, and how do you turn a board''s vague answer into something usable?', 'Risk appetite is how much risk the organisation is willing to accept to pursue its goals. Boards tend to answer in vibes, we are conservative, so my job is to translate that into thresholds people can actually apply: concrete statements about what losses, downtime, or exposure are acceptable in which areas, tied to real numbers and categories. The test is whether an analyst three levels down can look at a risk and know, from the stated appetite, whether to accept it or escalate.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_turning-risk-appetite-into-something-usable_f1', 'q_grc_mid_turning-risk-appetite-into-something-usable', 1, 'The board says ''we have no appetite for risk.'' What do you tell them?', 'That zero risk means doing nothing, which is not an option, so the real question is which risks and how much, where. I help them say it in trade-offs: we will not accept risks that threaten customer data or safety, and we will accept measured operational risk to move fast. Vague absolutes are unusable; prioritised trade-offs are policy.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_turning-risk-appetite-into-something-usable_f2', 'q_grc_mid_turning-risk-appetite-into-something-usable', 2, 'How does risk appetite actually change a day-to-day decision?', 'It sets the line for who can accept what. A risk inside appetite can be signed off locally; one outside it has to escalate. Without that line, every decision is an argument, and risks get accepted by whoever is most tired, not by whoever should own them.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_soc2-type-1-vs-2', 'grc', 'assurance', 'mid', 'SOC 2 Type I versus Type II: which does a customer actually want from you, and why?', 'Type I says your controls are designed properly at a single point in time; Type II says they actually operated effectively over a period, usually several months. A customer doing real due diligence wants Type II, because design on paper is cheap and what they care about is that the controls worked day after day, not that they looked right on one Tuesday. Type I is a reasonable first step for a young company, but it is a promise, where Type II is evidence.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_soc2-type-1-vs-2_f1', 'q_grc_mid_soc2-type-1-vs-2', 1, 'A startup has only a Type I. Is that a dealbreaker?', 'Not necessarily, if they are early and have a Type II window in progress, because everyone starts somewhere. I would read it as design is in place, operation is unproven, and weigh it with where the company is, rather than reject it outright or treat it as equal to a Type II.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_soc2-type-1-vs-2_f2', 'q_grc_mid_soc2-type-1-vs-2', 2, 'Why can a company not just keep renewing Type I and skip Type II?', 'Because a serious customer will stop accepting it: repeatedly proving only the design, never the operation, starts to look like avoidance. Type I over and over says we keep checking the blueprint and never the building, and buyers notice.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_overlapping-frameworks', 'grc', 'frameworks', 'mid', 'You have to comply with three overlapping frameworks. How do you avoid doing everything three times?', 'By controlling once and mapping to many. Most frameworks ask for the same underlying things in different words, access control, logging, incident response, so I build a single set of real controls and a mapping that shows how each one satisfies the relevant requirement in each framework. Then evidence is collected once and pointed at three sets of requirements. The waste comes from treating each framework as its own universe; the saving comes from seeing that they mostly overlap.', 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_overlapping-frameworks_f1', 'q_grc_mid_overlapping-frameworks', 1, 'What is the risk of mapping frameworks together carelessly?', 'Claiming a control covers a requirement it does not quite meet, so a gap hides inside a tidy-looking map. The mapping has to be honest about where a framework asks for something extra, or you pass three audits on paper and fail the one that reads closely.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_overlapping-frameworks_f2', 'q_grc_mid_overlapping-frameworks', 2, 'Where does the overlap approach break down?', 'At the edges where a framework genuinely demands something specific the others do not, a particular control, a particular report. Those you handle individually, so the right model is one shared core plus a small set of framework-specific extras, not one-size-fits-all.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, difficulty, created_at) VALUES ('q_grc_mid_two-hundred-open-exceptions', 'grc', 'operations', 'mid', 'Your exception process has two hundred open exceptions. What does that tell you, and what do you do?', 'That the policy and the reality have drifted apart: when there are two hundred standing exceptions, the exception has become the norm, and either the controls are unworkable or nobody is closing them. I would triage them by risk, find the clusters, because a hundred exceptions to one control means that control is wrong or unimplementable, and either fix the policy to match a sane reality or actually remediate and close. A pile of permanent exceptions is risk you have quietly accepted without deciding to.', 2, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_two-hundred-open-exceptions_f1', 'q_grc_mid_two-hundred-open-exceptions', 1, 'A hundred of them are against the same control. What does that mean?', 'That the control, not the hundred teams, is the problem: when everyone needs an exception to the same rule, the rule is unworkable or wrong for the environment. The fix is to redesign that control, not to keep rubber-stamping exceptions to it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_two-hundred-open-exceptions_f2', 'q_grc_mid_two-hundred-open-exceptions', 2, 'Exceptions have no expiry date. Why is that dangerous?', 'Because a temporary exception with no end becomes permanent by default, and the risk it was meant to time-box just lives on unreviewed. Every exception needs an owner and a review date, or the backlog is really a list of risks nobody is accountable for anymore.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, difficulty, created_at) VALUES ('lab_soc_ssh-brute-to-persistence', 'Three failures, one success, and then what', 'soc', 'fresher', 'A web server has been handed to you after a monitoring alert about failed SSH logins. The alert closed itself when the failures stopped. You have the day''s auth.log. Work out whether anything actually happened, and be ready to say what you would do in the next ten minutes.', 'log', 'auth.log', 1, 1, '2026-11-22T07:15:26.590Z');
