INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_dns-txt-exfil_t1', 'lab_network_dns-txt-exfil', 1, 'One host stands out. Which, and name the three properties of its traffic that make it stand out.', 'fin-lap-14 at 10.14.9.61. Three properties: every one of its queries is TXT while every other host asks for A records; the queries land roughly every thirty seconds with very little drift, which is a machine not a person; and the labels are long and high-entropy rather than readable names. Any one alone is weak. Together they are the signature.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_dns-txt-exfil_t2', 'lab_network_dns-txt-exfil', 2, 'The domain is cdn-sync-eu.net, which sounds like infrastructure. Does that make it less suspicious?', 'No, and the name is doing exactly the work it was chosen to do. Anyone can register a plausible-sounding domain, and the point of a name like that is to survive a quick glance at a log. Judge it on behaviour, on when the domain was registered, and on which process is asking, not on whether the string sounds like a CDN.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_dns-txt-exfil_t3', 'lab_network_dns-txt-exfil', 3, 'What technique is this, and what tells you the direction of the data?', 'DNS tunnelling for exfiltration. The data travels out in the query labels, which is why they are long and random-looking, and the answers come back as TXT records around 215 to 225 bytes, which is consistent enough to be a protocol rather than a varied set of real records. Sustained small two-way volume at a fixed interval is a channel, not lookups.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_dns-txt-exfil_t4', 'lab_network_dns-txt-exfil', 4, 'How would you confirm it is exfiltration rather than a misconfigured security or telemetry agent?', 'Go to the host and find the process making the queries, which settles it faster than any amount of log analysis. Compare with ops-srv-02 in the same file: that one queries its vendor by a readable name for A records, which is what legitimate telemetry looks like. Also check whether any other host in the estate talks to this domain. A single host alone is a compromise, not a deployment.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_network_dns-txt-exfil_t5', 'lab_network_dns-txt-exfil', 5, 'What do you block, and what is the risk of the block you chose?', 'Sinkhole cdn-sync-eu.net at the resolver and isolate fin-lap-14. The risk is narrow and acceptable: if you are wrong you break one tool on one laptop and hear about it within minutes. Blocking TXT records generally, or the resolver itself, would be an outage you caused while chasing a maybe. Sinkhole rather than drop, so you keep seeing which hosts try to reach it.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, difficulty, created_at) VALUES ('lab_soc_phish-header-read', 'Read the headers, not the signature', 'soc', 'fresher', 'A user forwarded this to the security mailbox saying it looked odd. Another user on the same floor has already clicked. Read the headers and be ready to answer the question the service desk will ask you in a minute: is it real, and what do we do now.', 'log', 'reported-message.eml', 0, 2, '2026-11-22T07:15:26.590Z');
