DELETE FROM lab_tasks WHERE lab_id = 'lab_soc_phish-header-read';
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_phish-header-read_t1', 'lab_soc_phish-header-read', 1, 'Does this message come from who it claims to? Point at the specific headers that decide it.', 'No. The From header says it-helpdesk@northfield.co.in, but Authentication-Results reports spf=fail, dkim=none and dmarc=fail for header.from=northfield.co.in. The From header is display text that anyone can set; the authentication results are the check. Those three lines together are the answer.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_phish-header-read_t2', 'lab_soc_phish-header-read', 2, 'If the user hits reply, where does the mail actually go, and why does the envelope differ again?', 'To helpdesk.verify@mail-secure-portal.com, from the Reply-To header, not to the address shown in From. Return-Path is different again, billing@acme-payroll-support.com, which is where bounces go. Three different addresses in one message, each serving a different purpose for the sender, is itself a strong indicator.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_phish-header-read_t3', 'lab_soc_phish-header-read', 3, 'What does the Received chain tell you about where this was actually sent from?', 'Read it bottom up, because each hop prepends itself. The earliest hop you can trust is your own edge, mx3.northfield.co.in, which received it from 91.214.76.33, a hosting provider VPS. A message claiming to be from internal IT should have originated inside the estate or from the sanctioned mail provider, not a rented VPS. X-Originating-IP agrees, but trust the Received line your own server wrote, not a header the sender supplied.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_phish-header-read_t4', 'lab_soc_phish-header-read', 4, 'The link is northfield-co-in.mail-secure-portal.com. Explain to a non-technical user why that is not your domain.', 'The domain is only ever what sits immediately to the left of the final .com: here that is mail-secure-portal. Everything before it is a subdomain the attacker can name anything, including your company with the dots swapped for hyphens so it reads right at a glance. Teach people to read from the right-hand end, and stop teaching the padlock as a safety signal, because that site will have a valid certificate.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_phish-header-read_t5', 'lab_soc_phish-header-read', 5, 'A user on the same floor entered their credentials. What are your first three actions?', 'Reset the password and invalidate active sessions and tokens, because resetting alone leaves a live session in the attacker''s browser. Check the mailbox for rules created after the click, which is the usual first move after a mailbox compromise, and look for sent items you did not expect. Then search the mail platform for other recipients by sender, originating address and URL rather than exact subject, and report delivered against clicked, because that is the number the business will ask for.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, difficulty, created_at) VALUES ('lab_soc_alert-queue-triage', 'Eighteen alerts, one shift, pick your order', 'soc', 'fresher', 'Your queue at the start of a shift. Nobody has triaged any of it. You will not get through all eighteen before the handover, so the question is not what each alert means, it is which ones you open first and what you can safely leave. Sort and filter as much as you like.', 'table', 'queue-0800-0915.csv', 1, 2, '2026-11-22T07:15:26.590Z');
