INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_alert-queue-triage_t1', 'lab_soc_alert-queue-triage', 1, 'Which alert do you open first, and why that one rather than the Critical?', 'A-4485, the new inbox rule on p.sharma from 196.251.88.4, rated Low. Creating a mailbox rule is the standard first move after a mailbox compromise, and that source address is the same one as the impossible-travel alert at 08:14. The Critical, A-4480, is ransomware heuristics on test-vm-03 under lab-admin, which is a test machine behaving like a test machine. Severity is a property of the rule, not of your environment.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_alert-queue-triage_t2', 'lab_soc_alert-queue-triage', 2, 'Four alerts chain together into one story. List them in order and say what the story is.', 'A-4481 to A-4484, four MFA denials on p.sharma from 103.21.58.12 between 08:40 and 08:42, then A-4485, the inbox rule from a completely different address at 08:44. Someone had the password and was pushing MFA prompts hoping she would accept one. Something then succeeded, because a rule got created two minutes later. A-4476, impossible travel on svc-reporting from that same 196.251.88.4, is the same actor on a second account.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_alert-queue-triage_t3', 'lab_soc_alert-queue-triage', 3, 'Five alerts are the same rule on five different hosts. Are they an incident?', 'The EICAR detections, A-4471 to A-4473, A-4486. EICAR is a harmless test string every product is required to detect, so this is either someone running a deliberate test or a file circulating with the string in it. Worth one note and a question to whoever is testing, not worth your first hour. The useful instinct is noticing that five identical High alerts across unrelated users is a pattern about your tooling, not about an attacker.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_alert-queue-triage_t4', 'lab_soc_alert-queue-triage', 4, 'A-4487 says the admin group changed, by svc-reporting. Why does that matter more now than it would on its own?', 'Because svc-reporting is the account in A-4476 with impossible travel from the same address as the inbox rule. On its own, a service account changing admin membership is a change-control question. In this queue it is the same actor arriving at privilege, roughly an hour after the first mailbox. That is the alert that turns this from a phishing incident into a domain problem.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_alert-queue-triage_t5', 'lab_soc_alert-queue-triage', 5, 'Which alerts can you genuinely leave for the next shift, and how do you leave them?', 'The EICAR batch, the three failed-logon Lows from 45.148.10.77 with its matching port scan, and the certificate expiry. The scanner is background internet noise and the certificate is a ticket, not an alert. Leave them closed or deferred with one line each saying why, not open and untouched. An alert passed on with no note is the same as one nobody read.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, difficulty, created_at) VALUES ('lab_soc_psexec-lateral', 'One service account, three servers, ninety seconds apart', 'soc', 'mid', 'Security events from three Windows servers and one workstation, pulled after a detection fired on the domain controller and was closed as a false positive by the previous shift. Reconstruct what happened and decide what you tell the business.', 'log', 'security-events-1119.log', 0, 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO lab_artifacts (lab_id, body, bytes) VALUES ('lab_soc_psexec-lateral', '11/19/2026 03:12:04 PM  4624  An account was successfully logged on.  Subject: SYSTEM  Logon Type: 3  Account Name: svc-sql  Source Network Address: 10.14.11.8  Authentication Package: NTLM  Workstation Name: ENG-WKS-21  Target: FIN-SRV-04
