DELETE FROM lab_tasks WHERE lab_id = 'lab_soc_psexec-lateral';
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_psexec-lateral_t1', 'lab_soc_psexec-lateral', 1, 'What authentication pattern tells you this is lateral movement rather than normal administration?', 'Every logon is type 3 with NTLM, from one workstation, ENG-WKS-21 at 10.14.11.8, against three different servers within nine minutes, each immediately followed by 4672 granting SeDebugPrivilege and SeImpersonatePrivilege. Admins log in interactively or over RDP from a jump host; they do not hit three servers over the network in ninety-second intervals. NTLM rather than Kerberos on a domain is the tell that the hash is being used rather than a password.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_psexec-lateral_t2', 'lab_soc_psexec-lateral', 2, 'A service was installed. What is it, and why is that line the one you would show a manager?', 'Event 7045, PSEXESVC installed as LocalSystem on FIN-SRV-04, then 4688 showing services.exe spawning PSEXESVC.exe which spawns cmd.exe. That is remote execution as SYSTEM. It is the line for a manager because it needs no interpretation: a remote-execution service was installed on a finance server by a SQL service account, and nobody raised a change for it.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_psexec-lateral_t3', 'lab_soc_psexec-lateral', 3, 'Two commands are credential theft. Name them and say what the attacker walks away with.', 'reg save HKLM\SAM and reg save HKLM\SYSTEM at 03:13, which together let the local account hashes be extracted offline. Then ntdsutil ifm create full on DC-01 at 03:21, which builds a copy of the entire Active Directory database including every domain hash. After that second one, assume every credential in the domain is compromised and plan a full reset, not a targeted one.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_psexec-lateral_t4', 'lab_soc_psexec-lateral', 4, 'The svc-sql account fails on DC-01 at 03:16:58, then a.verma succeeds at 03:21 from the same workstation. What happened in between?', 'The service account hit an account restriction on the domain controller, so it could not get in. Five minutes later a different and more privileged account works from the same source. The hashes dumped from the two member servers at 03:13 are the obvious bridge: a.verma had logged on somewhere the attacker could reach. Note the 08:30 entry: a.verma logs on interactively at her own workstation that morning, which is how her credential came to be on a machine at all.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_soc_psexec-lateral_t5', 'lab_soc_psexec-lateral', 5, 'The previous shift closed this as a false positive. What do you do about that, beyond the incident?', 'Handle the incident first, then find out why it was closable. Was the evidence genuinely ambiguous at the time, was the queue too deep, or did the runbook say to close it. One analyst making one call is almost never the real finding. If the runbook told them to close it, fix the runbook and say so to the team, because the alternative teaches everyone that following the process is risky.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, difficulty, created_at) VALUES ('lab_network_webshell-in-access-log', 'The scan that found something', 'network', 'fresher', 'Half an hour of web server access logs from a shop front end, pulled because the hosting bill showed unusual outbound transfer. Most of what you see is ordinary. Find the part that is not, and work out how far it went.', 'log', 'access.log', 1, 1, '2026-11-22T07:15:26.590Z');
