DELETE FROM lab_tasks WHERE lab_id = 'lab_pentest_nmap-what-first';
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_pentest_nmap-what-first_t1', 'lab_pentest_nmap-what-first', 1, 'Which finding would you chase first, and why it rather than the obvious ones?', 'Redis on 6379 responding without authentication. It is unauthenticated access to a data store, reachable now, with no exploit chain required, and on many deployments it leads straight to writing files as the service user. The obvious ones, old MySQL and an expired certificate, are findings but neither hands you access in the first ten minutes.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_pentest_nmap-what-first_t2', 'lab_pentest_nmap-what-first', 2, 'Anonymous FTP is open with a backups directory. What do you do, and what do you not do?', 'Log in, list the directory, and record what is exposed and its size. Do not download the backups: on an engagement you are proving exposure, not exfiltrating client data, and pulling a database backup onto your machine creates a liability you did not need. Note the filenames and dates, screenshot the listing, and describe the impact.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_pentest_nmap-what-first_t3', 'lab_pentest_nmap-what-first', 3, 'The certificate expired in March 2025 and is self-signed. How do you rate that, honestly?', 'Low on its own, and say so rather than padding the report. It is a staging host; self-signed is common there and the real risk is that it trains staff to click through warnings. The more interesting observation is what it implies: a certificate nobody renewed for eighteen months suggests the host is unowned, which is usually true of the rest of its patching too.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_pentest_nmap-what-first_t4', 'lab_pentest_nmap-what-first', 4, 'Jenkins on 8080 returns 403 and Elasticsearch on 9200 is open. Which is the bigger problem and why?', 'Elasticsearch, because 403 on Jenkins means something is refusing you while an open 9200 typically means the cluster API answers without authentication, so you can read every index. Jenkins is still worth revisiting, since 403 from the root does not mean every endpoint is protected and Jenkins is a credential store with deploy access when it is not. But start where the data is already readable.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_pentest_nmap-what-first_t5', 'lab_pentest_nmap-what-first', 5, 'The client says this is only staging, so none of it matters. Respond.', 'Ask one question: does staging hold production data, and can staging reach production. Both are usually yes, and the answer to either turns this into a production finding. Staging is where the controls are relaxed and the data is real, which is exactly why it gets attacked. Put the answer in the report in their words rather than arguing in the room.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, difficulty, created_at) VALUES ('lab_pentest_idor-and-mass-assignment', 'Same token, someone else''s invoice', 'pentest', 'mid', 'Five request and response pairs from your proxy during an authenticated API test. You are signed in as account 8812 throughout and never change the token. Work out what you have, and what you would write.', 'log', 'proxy-history.http', 0, 3, '2026-11-22T07:15:26.590Z');
INSERT OR REPLACE INTO lab_artifacts (lab_id, body, bytes) VALUES ('lab_pentest_idor-and-mass-assignment', '### Request 1
GET /api/v2/invoices/4471 HTTP/1.1
Host: billing.northfield.co.in
Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.PAYLOAD_USER_8812.SIG
Accept: application/json

### Response 1
HTTP/1.1 200 OK
Content-Type: application/json

{"id":4471,"account_id":8812,"customer":"Rohit Menon","amount":"18400.00",
 "currency":"INR","status":"paid","pdf":"/api/v2/invoices/4471/pdf"}

### Request 2
GET /api/v2/invoices/4472 HTTP/1.1
Host: billing.northfield.co.in
Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.PAYLOAD_USER_8812.SIG
Accept: application/json

### Response 2
HTTP/1.1 200 OK
Content-Type: application/json

{"id":4472,"account_id":9043,"customer":"Sunita Rao","amount":"226500.00",
 "currency":"INR","status":"unpaid","pdf":"/api/v2/invoices/4472/pdf"}

### Request 3
GET /api/v2/accounts/9043 HTTP/1.1
