DELETE FROM lab_tasks WHERE lab_id = 'lab_cloud_leaked-key-in-the-trail';
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_cloud_leaked-key-in-the-trail_t1', 'lab_cloud_leaked-key-in-the-trail', 1, 'Two things about the 10:41 events say compromise before you read a single API call. What are they?', 'The source address and the region. The deploy-ci key operates from 13.233.44.9 in ap-south-1 in the morning and again at 11:30, but at 10:41 the same key is used from 45.148.10.77 in us-east-1. One credential, two origins, and a region the account does not use. Identity plus location plus region is the fastest triage you have in a cloud account.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_cloud_leaked-key-in-the-trail_t2', 'lab_cloud_leaked-key-in-the-trail', 2, 'The attacker gets two AccessDenied results. Why are failures useful to you here?', 'ListUsers and ListRoles both fail, which tells you the key was reasonably scoped and that they were enumerating rather than acting with knowledge. It also dates their reconnaissance precisely. Denied calls are evidence of intent and of what your least-privilege work actually bought you, which is worth saying out loud when someone asks whether the controls helped.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_cloud_leaked-key-in-the-trail_t3', 'lab_cloud_leaked-key-in-the-trail', 3, 'AssumeRole at 10:51 is the pivot. Explain what changes after it and why the identity column matters.', 'Before it, the actor is the deploy-ci key with limited permissions. After it, the identity becomes ops-admin-role as an AssumedRole and everything succeeds. The deploy key was allowed to assume an operations role, so the blast radius was never the key''s own policy, it was whatever it could assume. Trust relationships, not attached policies, are what decide how far a leaked credential reaches.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_cloud_leaked-key-in-the-trail_t4', 'lab_cloud_leaked-key-in-the-trail', 4, 'Three events in ninety seconds set up long-term access. Name them and say what you do about each.', 'CreateUser, AttachUserPolicy and CreateAccessKey between 10:52:40 and 10:52:49, and the new identity svc-maintenance appears using its key at 11:02. Delete the user and its key rather than just disabling it, audit everything it did in that window, and check for any other identity created that day. Revoking deploy-ci alone leaves the attacker signed in under a name that looks like it belongs.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_cloud_leaked-key-in-the-trail_t5', 'lab_cloud_leaked-key-in-the-trail', 5, 'StopLogging at 10:55 is the last thing they do. What does that mean for everything after it?', 'Your trail ends there, so you cannot treat 11:02 as the last activity and you cannot say what happened between the stop and whenever logging came back. Say that plainly. Then check whether anything was shipping these events elsewhere, a log archive or a sibling account, because a copy outside the compromised account is the only thing that survives this move. If there is none, that is the finding to fix first.');

INSERT OR REPLACE INTO labs (id, title, role, level, brief, artifact_kind, artifact_name, is_free, difficulty, created_at) VALUES ('lab_grc_access-review-extract', 'Sign here to say this access is correct', 'grc', 'fresher', 'The quarterly access review extract for three systems. A manager is about to approve all of it in one click, which is what happened last quarter. Read it properly and find what should not be there. Sort by any column.', 'table', 'access-review-q4.csv', 0, 1, '2026-11-22T07:15:26.590Z');
