DELETE FROM lab_tasks WHERE lab_id = 'lab_grc_access-review-extract';
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_grc_access-review-extract_t1', 'lab_grc_access-review-extract', 1, 'Two rows should have been removed by the leaver process. Find them and say what the real finding is.', 'n.gupta in CRM and t.pillai in ERP, both marked Left in HR status and both still holding entitlements. The real finding is not two accounts, it is that the leaver process does not reach these systems, so the number is however many people have left since it last worked. Report the control failure with these two as evidence, not the two as the issue.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_grc_access-review-extract_t2', 'lab_grc_access-review-extract', 2, 'One row is a segregation-of-duties problem. Which, and why does it matter in a finance system?', 's.rao holds both AP Clerk and AP Approver in the ERP. The same person can raise a payment and approve it, which is the classic fraud path and the first thing an auditor tests in accounts payable. Note also d.iyer, an engineer still holding AP Approver from 2022 with no ERP login since April 2025: not a conflict, but an engineer who can approve payments.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_grc_access-review-extract_t3', 'lab_grc_access-review-extract', 3, 'Two entitlements grant administrator rights in production. Say what you would ask about each.', 'v.das, a contractor with AdministratorAccess to AWS Prod since February, and svc-backup, a service identity with AdministratorAccess since 2021. For the contractor: what does the contract end date say, and why administrator rather than scoped. For the service: what does a backup job actually need, because it is almost never everything, and who holds its credentials. Service accounts skip reviews precisely because no human owns them.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_grc_access-review-extract_t4', 'lab_grc_access-review-extract', 4, 'What is wrong with the ops-shared row, independent of what it can do?', 'It is a shared account, so no action taken with it can be attributed to a person. That breaks accountability for every other control: logging, review, and any investigation that lands on it. Granted in 2021 and used yesterday, so it is live. The recommendation is named accounts with a role, and if the shared one must survive, a checkout process with a named owner at minimum.');
INSERT INTO lab_tasks (id, lab_id, position, prompt, model_answer) VALUES ('lab_grc_access-review-extract_t5', 'lab_grc_access-review-extract', 5, 'The manager says everyone on the list needs their access. How do you make the review mean something?', 'Stop asking them to confirm a list and start asking a specific question per row, in business terms: does this person still need to approve payments. Show what the entitlement permits rather than its name, pre-flag the rows that contradict HR data or have not been used in ninety days, and require a reason to keep anything flagged. A review where everything is approved in one click is a signature, not a control, and it will not survive an audit.');

INSERT OR REPLACE INTO scenarios (id, role, level, title, situation, ask, minutes, model_answer, is_free, created_at) VALUES ('sc_soc_unacked-alert', 'soc', 'fresher', 'The alert nobody acknowledged', 'At 03:12 an EDR alert fired on a finance workstation: WINWORD.EXE spawned rundll32.exe, which then made an outbound connection. Nobody acknowledged it. You arrive at 09:00 and the alert is still open and unassigned. The user is at their desk, working normally, and has no idea anything happened.', 'Write what you do in your first thirty minutes, in the order you would do it, and state what specifically would make you escalate this rather than close it.', 20, 'The first question is not what happened six hours ago, it is what is true right now. Check whether the process is still running, whether anything was written that survives a reboot, and whether that outbound connection is still being made. Those three answers change everything that follows.

Before you touch the machine, decide that you are not going to destroy what is on it. The single most common way a fresher loses this incident is telling the user to restart, or restarting it themselves to "clear" the alert. Memory is where the answer lives and a reboot throws it away.

The signal here is the chain, not the binary. rundll32.exe is a signed Microsoft component and on its own it is noise. WINWORD.EXE as its parent is the finding, because documents do not legitimately need to do that. Pull the full process tree, the command line, and the document that was open.

Then scope it. The same document almost certainly went to more than one person. Search for the parent chain, the file hash, the sender and the destination address across the estate before you convince yourself this is one machine.

Containment is a business decision with a security recommendation attached. Say what you recommend and who you need to approve it. On a finance workstation with payment access, isolating the host and keeping it powered on is usually the right call, and you should be able to say why you would not simply pull the network cable.

Escalate on any of: an established outbound session to infrastructure you cannot attribute, evidence of credential access, any sign of movement to a second host, or persistence that survives reboot. Also escalate on the clock: an alert that sat for six hours on a host with payment access is itself worth reporting, separately from whatever the alert turns out to be.

Last, be careful what you say to the user. You need them to stop working and not touch the machine. You do not need to tell them they have been compromised before you know it.', 1, '2026-11-22T07:15:26.590Z');
DELETE FROM scenario_points WHERE scenario_id = 'sc_soc_unacked-alert';
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_unacked-alert_p1', 'sc_soc_unacked-alert', 1, 'Establishes whether it is still live before anything else', 'Process still running, persistence written, connection still open. Six hours of lag does not mean it is over, and it does not mean it is not.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_unacked-alert_p2', 'sc_soc_unacked-alert', 2, 'Preserves the host instead of clearing it', 'No reboot, no "just restart it" to the user, no deleting the file to make the alert go away. Volatile evidence is the evidence that answers this.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_unacked-alert_p3', 'sc_soc_unacked-alert', 3, 'Reads the parent chain, not the binary name', 'rundll32.exe alone is signed and ordinary. WINWORD.EXE spawning it is the finding. A candidate who treats the binary as the indicator will chase noise forever.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_unacked-alert_p4', 'sc_soc_unacked-alert', 4, 'Scopes beyond the one host', 'Same document, same sender, same hash, same destination, across the estate. A phishing document that reached one finance user reached others.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_unacked-alert_p5', 'sc_soc_unacked-alert', 5, 'Separates the recommendation from the decision', 'Says what containment they advise and who authorises it. Isolating a finance workstation during month end has a cost that is not the analyst’s to absorb silently.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_unacked-alert_p6', 'sc_soc_unacked-alert', 6, 'Names escalation triggers concretely', 'Unattributed outbound session, credential access, a second host, reboot-surviving persistence. "If it looks bad" is not a trigger.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_unacked-alert_p7', 'sc_soc_unacked-alert', 7, 'Raises the six hours as its own finding', 'An unacknowledged alert overnight on a host with payment access is a coverage problem that exists whether or not this alert turns out to be real.');

INSERT OR REPLACE INTO scenarios (id, role, level, title, situation, ask, minutes, model_answer, is_free, created_at) VALUES ('sc_soc_closed-as-benign', 'soc', 'mid', 'The alert that was closed as benign', 'Five weeks ago an analyst closed an alert for a PowerShell download cradle on a build server. The closure note reads: "sysadmin confirmed this is their deployment script, benign true positive". Today that build server is making an outbound request to a domain registered eleven days ago, at a near-exact sixty second interval. The sysadmin who gave that confirmation left the company three weeks ago.', 'Write how you handle this. Include what you do about the original closure, and what you would say to your manager about it.', 25, 'Work the live thing first. The archaeology matters and it will matter more later, but right now there is a host beaconing and that is the emergency.

A near-exact sixty second interval is not how software behaves when it is doing its job. Real polling jitters. Pull the process that owns the connection, map it to its parent, and get the full request: host header, URI, user agent, certificate, response size. The regularity itself is evidence and you should say so.

Then ask the question that makes a build server different from any other host. A build server holds signing material, deploy credentials, and write access to artifacts that other machines trust and execute. The incident is not "a server is beaconing", it is "the machine that signs our software is beaconing". That changes the severity, the people you wake, and how fast you move.

Containment on a build server stops releases, so this is a conversation, not a unilateral action. Have the recommendation ready and the cost understood. Isolating it from everything except your analysis path, while keeping it running, is usually the opening position.

Now the closure. Re-open it. A confirmation from a person, with no artifact attached, was never evidence, and it is certainly not evidence now that the person cannot be asked. Go and find the script they referred to, in version control, with a commit date. Either it exists and matches what fired, or the closure was a guess that happened to end the ticket.

Treat the five weeks as a scoping window, not as a fact. Ask what that host reached in that period, what artifacts it produced, and what consumed them.

To your manager: lead with the live incident and the build server exposure. Then name the process finding without naming the analyst as the problem. The failure is that a closure could rest on a verbal confirmation with nothing attached and nothing to re-check. The fix is that closures of that class require a linked artifact, and that anything touching build or signing infrastructure does not get closed by a single analyst at all.', 0, '2026-11-22T07:15:26.590Z');
DELETE FROM scenario_points WHERE scenario_id = 'sc_soc_closed-as-benign';
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_closed-as-benign_p1', 'sc_soc_closed-as-benign', 1, 'Works the beacon before the history', 'There is a live finding and a stale one. Starting with the five week old ticket is the wrong order even though it is the more interesting story.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_closed-as-benign_p2', 'sc_soc_closed-as-benign', 2, 'Reads the fixed interval as the indicator', 'Legitimate polling jitters. Near-exact regularity is machine-to-machine on a schedule, and saying so shows they know what normal looks like.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_closed-as-benign_p3', 'sc_soc_closed-as-benign', 3, 'Recognises what a build server actually is', 'Signing material, deploy credentials, artifacts that other machines execute without question. This is a supply chain incident, not a server incident.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_closed-as-benign_p4', 'sc_soc_closed-as-benign', 4, 'Re-opens the closure on its merits', 'A verbal confirmation with no artifact was never evidence. The departure makes it unverifiable, but it was already unverifiable.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_closed-as-benign_p5', 'sc_soc_closed-as-benign', 5, 'Goes looking for the script in version control', 'Either the deployment script exists with a commit history that matches, or it does not. That is a question with an answer, and nobody asked it the first time.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_closed-as-benign_p6', 'sc_soc_closed-as-benign', 6, 'Treats five weeks as a scoping window', 'What did the host reach, what did it build, and what ran those artifacts. The dwell time sets the blast radius.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_closed-as-benign_p7', 'sc_soc_closed-as-benign', 7, 'Reports the process failure without blaming the analyst', 'The finding is that a closure could rest on nothing checkable. A candidate who makes this about one person’s mistake has misread what a manager needs to hear.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_soc_closed-as-benign_p8', 'sc_soc_closed-as-benign', 8, 'Prices the containment before recommending it', 'Isolating a build server stops releases. Knowing that, and saying it, is what separates a recommendation from a demand.');

INSERT OR REPLACE INTO scenarios (id, role, level, title, situation, ask, minutes, model_answer, is_free, created_at) VALUES ('sc_pentest_client-disputes-xss', 'pentest', 'fresher', 'The client says your finding is not real', 'You reported a stored cross-site scripting vulnerability in an internal admin panel. The client has pushed back in writing: the panel is only reachable over the corporate VPN, only twelve people hold accounts, and all twelve are long-serving trusted staff. They would like it downgraded to informational so it does not appear in the executive summary.', 'Write your reply to the client.', 20, 'Start by conceding what is true, because something in their objection is. A VPN and twelve accounts genuinely do reduce how likely this is to be exploited. If your reply pretends otherwise you have lost the argument and the relationship in one message.

Then separate the two things they have merged. Likelihood is how easy it is to reach. Impact is what happens when someone does. Their controls act on the first and do nothing at all to the second. Stored XSS in an admin panel means an attacker executes code in an administrator’s browser session, with everything that session can do. Whatever the panel administers, that is the impact, and it does not change because the door is further away.

Give them the path that survives their objection, specifically. One phished VPN credential. One of the twelve with a compromised workstation. One contractor laptop. None of these require an untrusted insider, which is the thing they are really telling you does not exist, and they are probably right about that.

Say what you will change honestly. If your methodology rates on likelihood as well as impact, then reduced reachability lowers the rating, and you should lower it and show the working. If it moves from high to medium, say that. What you cannot do is move it to informational, because informational means there is nothing to fix, and there is something to fix.

Then make it easy to close. Output encoding at the point of render, a content security policy that refuses inline script. Usually a small change in one component. A lot of pushback on findings is really a dispute about cost, and quoting the actual fix dissolves it.

Finally, record their position in the report next to the finding. If they accept the risk that is entirely their right, and a documented acceptance is a better outcome for everyone than a deleted finding.', 1, '2026-11-22T07:15:26.590Z');
DELETE FROM scenario_points WHERE scenario_id = 'sc_pentest_client-disputes-xss';
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_client-disputes-xss_p1', 'sc_pentest_client-disputes-xss', 1, 'Concedes the true part of the objection first', 'The VPN and twelve accounts really do reduce likelihood. A reply that starts by disagreeing with everything gets read as defensive and ignored.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_client-disputes-xss_p2', 'sc_pentest_client-disputes-xss', 2, 'Separates likelihood from impact explicitly', 'Their controls act on reachability. The consequence of exploitation is untouched. This distinction is the entire answer.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_client-disputes-xss_p3', 'sc_pentest_client-disputes-xss', 3, 'Explains what stored XSS in an admin panel actually means', 'Code executing in an administrator session, with that session’s authority. Naming the consequence beats naming the vulnerability class.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_client-disputes-xss_p4', 'sc_pentest_client-disputes-xss', 4, 'Gives an attack path that does not need a malicious insider', 'A phished VPN credential or a compromised workstation. The client is telling you their staff are trustworthy, and arguing with that is both rude and unnecessary.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_client-disputes-xss_p5', 'sc_pentest_client-disputes-xss', 5, 'Adjusts the rating honestly rather than holding the line', 'If the methodology scores likelihood, lower it and show the working. Refusing to move at all is as unprofessional as caving.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_client-disputes-xss_p6', 'sc_pentest_client-disputes-xss', 6, 'Refuses informational, and says why that word is the problem', 'Informational means nothing to fix. There is something to fix. That is the one point not to concede.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_client-disputes-xss_p7', 'sc_pentest_client-disputes-xss', 7, 'Quotes the actual fix', 'Output encoding and a CSP without inline script. Most pushback on findings is a dispute about effort, and the effort here is small.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_client-disputes-xss_p8', 'sc_pentest_client-disputes-xss', 8, 'Offers documented risk acceptance instead of deletion', 'Their risk to accept. A recorded acceptance protects the client, the tester and the next person to read the report.');

INSERT OR REPLACE INTO scenarios (id, role, level, title, situation, ask, minutes, model_answer, is_free, created_at) VALUES ('sc_pentest_da-on-day-one', 'pentest', 'mid', 'Domain admin, two hours in', 'Two hours into a two week internal engagement you hold domain admin, reached through an unconstrained delegation path. Scope is "internal network, no social engineering". The client is expecting two weeks of work and a report at the end of it.', 'Write what you do next, and what you tell the client today rather than in the report.', 25, 'Tell them today. A path to domain admin in two hours is not a report finding, it is a phone call. If that path exists for you it exists for anything already inside, and the client needs the chance to act on it now rather than in a fortnight.

Before you do anything else with the access, stop and work out what it reaches. Domain admin in most estates means backups, virtualisation, and every system that trusts the domain. The risk at this moment is not that you fail to find more, it is that you break something expensive and the engagement becomes about that instead.

Then get authorisation in writing before you use it further. Your scope said internal network. It did not say "and once you are domain admin, help yourself". Confirm what you may touch, what is off limits, and who you call if something goes wrong. Verbal approval on a call is fine as long as it is followed by an email that exists afterwards.

Now reframe the engagement. The remaining time just became more valuable, not less. You have thirteen days to answer questions the client cannot answer themselves: how far does this reach, what else is broken independently of it, and above all, can they see any of it. Nothing you do in the next two weeks is worth more than finding out whether a single alert fired while you took the domain in two hours.

Document the path to the standard where someone else can reproduce it and someone else can fix it. Unconstrained delegation specifically, on which object, reachable from where, and what the remediation actually is, because the fix is not obvious and clients get it wrong.

Resist collecting trophies. Domain admin makes it trivially easy to go and read the things you are curious about, and none of that is in scope. The authorisation you just got is narrower than your access, and that gap is where testers end careers.', 0, '2026-11-22T07:15:26.590Z');
DELETE FROM scenario_points WHERE scenario_id = 'sc_pentest_da-on-day-one';
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_da-on-day-one_p1', 'sc_pentest_da-on-day-one', 1, 'Tells the client the same day', 'A two hour path to domain admin does not wait for a report. Sitting on it to make the report impressive is the wrong instinct and clients notice.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_da-on-day-one_p2', 'sc_pentest_da-on-day-one', 2, 'Assesses blast radius before using the access further', 'Backups, virtualisation, everything that trusts the domain. The danger now is breaking something, not missing something.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_da-on-day-one_p3', 'sc_pentest_da-on-day-one', 3, 'Gets written authorisation before going further', 'Access is not permission. The original scope did not contemplate this, so it has to be extended deliberately rather than assumed.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_da-on-day-one_p4', 'sc_pentest_da-on-day-one', 4, 'Treats the remaining time as more valuable, not spare', 'Thirteen days to answer how far it reaches and what else is independently broken. A candidate who says "the engagement is basically done" has misunderstood what was bought.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_da-on-day-one_p5', 'sc_pentest_da-on-day-one', 5, 'Makes detection the headline question', 'Did anything fire while they took the domain in two hours? That answer is worth more to the client than the next five findings.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_da-on-day-one_p6', 'sc_pentest_da-on-day-one', 6, 'Documents the path to reproduce and to fix', 'Which object, which delegation, reachable from where. Unconstrained delegation remediation is commonly botched, so vague wording costs the client the fix.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_pentest_da-on-day-one_p7', 'sc_pentest_da-on-day-one', 7, 'Stays inside authorisation despite having the access', 'Domain admin makes everything reachable. Almost none of it is permitted. Naming that gap unprompted is what a panel is listening for.');

INSERT OR REPLACE INTO scenarios (id, role, level, title, situation, ask, minutes, model_answer, is_free, created_at) VALUES ('sc_grc_rubber-stamped-review', 'grc', 'fresher', 'The access review nobody can finish', 'It is the quarterly user access review. The finance application owner has 340 users to certify. They have now returned the same spreadsheet three times with every line marked "retain", including fourteen accounts belonging to people who left the company. The external audit fieldwork starts in two weeks.', 'Write how you handle this, including what you tell the auditor.', 20, 'The fourteen leavers are the urgent problem. The rubber stamp is the actual finding. Deal with them in that order and do not confuse them.

Disable the leaver accounts now. Not at the end of the review, not once the owner responds. An account belonging to someone who has left is live risk and it does not need a quarterly process to justify closing it.

Then stop treating the owner as the problem. Three hundred and forty rows, no context, no last login, no indication of which entitlements are dangerous, is a task that is structurally impossible to do honestly in the time anyone has for it. You designed a control that can only be passed by lying, and they passed it.

Make the review reviewable. Pre-filter by last login so dormant accounts surface on their own. Flag the privileged entitlements separately, because twelve rows that grant payment approval deserve more attention than three hundred that grant read access. Break it up by team so each line goes to someone who actually knows the person. Pre-tick nothing.

Reconcile against HR leaver data as a control in its own right, not as a courtesy to the owner. An access review that depends entirely on human recall will always miss leavers, because remembering absences is the thing people are worst at.

Tell the auditor before they find it. Say that the control operated ineffectively this period, that you identified it, that fourteen leaver accounts were remediated on a stated date, and what you are changing. A self-identified control failure with evidence of remediation is an ordinary audit conversation. The same failure discovered by the auditor in a sample is a finding with your credibility attached to it.

The durable fix is joiner-mover-leaver automation so that leaving triggers deprovisioning without anyone remembering. Say that, and say roughly what it costs, because the reason it has not been done is always that nobody put a number on it.', 0, '2026-11-22T07:15:26.590Z');
DELETE FROM scenario_points WHERE scenario_id = 'sc_grc_rubber-stamped-review';
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_rubber-stamped-review_p1', 'sc_grc_rubber-stamped-review', 1, 'Separates the urgent risk from the real finding', 'Fourteen live leaver accounts need closing today. The rubber stamping is the control failure. Both matter and they are not the same problem.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_rubber-stamped-review_p2', 'sc_grc_rubber-stamped-review', 2, 'Disables the leaver accounts immediately', 'Outside the review process, not at the end of it. Waiting for a quarterly workflow to close a departed employee’s access is the failure repeating itself.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_rubber-stamped-review_p3', 'sc_grc_rubber-stamped-review', 3, 'Treats the control design as the cause', '340 context-free rows can only be completed by ticking everything. The owner behaved exactly as the design invited. Blaming them fixes nothing.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_rubber-stamped-review_p4', 'sc_grc_rubber-stamped-review', 4, 'Makes the review possible to do honestly', 'Filter by last login, flag privileged separately, split by team, pre-tick nothing. Concrete redesign, not "provide training".');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_rubber-stamped-review_p5', 'sc_grc_rubber-stamped-review', 5, 'Reconciles against HR data as a control', 'Human recall will always miss leavers. A system-to-system reconciliation is the only version of this control that works.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_rubber-stamped-review_p6', 'sc_grc_rubber-stamped-review', 6, 'Discloses to the auditor rather than waiting to be caught', 'Self-identified with evidence of remediation is routine. Found in their sample is a finding plus a credibility problem.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_rubber-stamped-review_p7', 'sc_grc_rubber-stamped-review', 7, 'Names the structural fix with a cost attached', 'Joiner-mover-leaver automation. The reason it has not happened is that nobody priced it, so pricing it is part of the recommendation.');

INSERT OR REPLACE INTO scenarios (id, role, level, title, situation, ask, minutes, model_answer, is_free, created_at) VALUES ('sc_grc_vendor-refuses-questionnaire', 'grc', 'mid', 'The vendor who will not fill in your questionnaire', 'A SaaS vendor that will process customer personal data has declined your security questionnaire. They will provide their SOC 2 Type II report and a signed summary letter, and nothing else. Procurement wants to sign this week. The business owner says this vendor is the only one that does what the team needs.', 'Write your assessment and your recommendation.', 25, 'Do not reject this reflexively. A SOC 2 Type II is independently tested evidence over a period of time. Your questionnaire is a vendor describing themselves in their own words. In evidentiary terms the thing they offered is stronger than the thing you asked for, and a candidate who treats the refusal as obstruction has it backwards.

Read the report properly, which most people do not. Check the period it covers and whether it has lapsed. Check which trust services criteria are in scope, because security alone does not tell you anything about availability or confidentiality. Check the system description and confirm the service you are buying is actually the system that was audited, which is frequently is not. Check the subservice organisations and whether they are carved out, because a carve-out means a chunk of the stack was never examined.

Then go to the exceptions and read them slowly. The exceptions are the report. A clean opinion with three exceptions around access revocation tells you more than the entire control narrative, and it is the part people skip.

Now do the work that the report cannot do for you: map their controls to your actual requirements rather than to your form. The questionnaire was only ever a vehicle for those requirements, and if the report answers one you can stop asking.

Whatever it does not answer goes into the contract instead of into another spreadsheet. Breach notification within a defined number of hours. Data location and whether it can change. Deletion on exit with evidence. Notice before a new subprocessor. Right to audit or to receive the next report. These are enforceable in a way a questionnaire answer never was.

Recommend a conditional yes with those terms, a defined review date, and the residual risk written down and formally accepted by the business owner who told you there is no alternative. Blocking a sole-source vendor on a process objection is how security teams get routed around, and being routed around is worse than the risk you were trying to manage.', 0, '2026-11-22T07:15:26.590Z');
DELETE FROM scenario_points WHERE scenario_id = 'sc_grc_vendor-refuses-questionnaire';
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_vendor-refuses-questionnaire_p1', 'sc_grc_vendor-refuses-questionnaire', 1, 'Recognises the SOC 2 as stronger evidence, not weaker', 'Independently tested over a period versus vendor self-description. Treating the refusal as obstruction is the error this scenario is built to catch.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_vendor-refuses-questionnaire_p2', 'sc_grc_vendor-refuses-questionnaire', 2, 'Checks the period and whether it has lapsed', 'A report covering a window that ended fourteen months ago says very little about today.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_vendor-refuses-questionnaire_p3', 'sc_grc_vendor-refuses-questionnaire', 3, 'Checks scope and the system description', 'Which criteria were covered, and whether the audited system is the product being bought. They are often not the same thing.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_vendor-refuses-questionnaire_p4', 'sc_grc_vendor-refuses-questionnaire', 4, 'Looks for carved-out subservice organisations', 'A carve-out means part of the stack was never examined. What is excluded is the interesting part of any assurance report.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_vendor-refuses-questionnaire_p5', 'sc_grc_vendor-refuses-questionnaire', 5, 'Reads the exceptions as the substance', 'The exceptions are where the report tells the truth. Skipping to the opinion page is the most common way this document gets misread.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_vendor-refuses-questionnaire_p6', 'sc_grc_vendor-refuses-questionnaire', 6, 'Maps controls to requirements, not to the form', 'The questionnaire was a vehicle for requirements. Anything the report answers does not need asking again.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_vendor-refuses-questionnaire_p7', 'sc_grc_vendor-refuses-questionnaire', 7, 'Moves the gaps into the contract', 'Breach notification time, data location, deletion on exit, subprocessor notice, right to the next report. Enforceable, unlike a questionnaire answer.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_grc_vendor-refuses-questionnaire_p8', 'sc_grc_vendor-refuses-questionnaire', 8, 'Recommends a conditional yes with accepted residual risk', 'A sole-source vendor blocked on process gets the security team routed around. Conditions plus a named risk owner is the outcome that actually holds.');

INSERT OR REPLACE INTO scenarios (id, role, level, title, situation, ask, minutes, model_answer, is_free, created_at) VALUES ('sc_cloud_public-bucket-no-logs', 'cloud', 'mid', 'Public for nine months, with no access logs', 'An engineer reports that a storage bucket holding customer-uploaded documents has carried a public read policy since a platform migration nine months ago. Access logging was never enabled on the bucket. The business is asking you whether customer data was taken.', 'Write how you establish what actually happened, and what you advise the business.', 25, 'Close the exposure first, but close it carefully. Change the policy, and before you do, check whether anything legitimate is currently reading from it anonymously, because nine months is long enough for something to have quietly come to depend on it. Breaking production while fixing an exposure turns one incident into two.

Then say the uncomfortable thing plainly, early, and in writing: with no access logs you cannot prove that nothing was taken. You can gather evidence that makes access more or less likely. You cannot produce the negative. Every hour you spend letting the business believe otherwise is an hour they are not spending on the decision they actually have to make.

Go after secondary evidence. Control plane logs will tell you when and by whom the policy was set, which is a different question from who read it, and still worth knowing. If there is a CDN or a load balancer in front, its logs may cover some of the window. Billing data is underrated here: a sustained change in egress is visible long after request logs are gone, and an absence of unusual egress is weak but real evidence.

Establish what was actually in the bucket and, separately, whether the names were discoverable. A public bucket that also permitted listing is a fundamentally different incident from one where an attacker would have had to guess a document name. If objects are named with high-entropy identifiers and listing was denied, your exposure is far narrower, and that distinction should be in the first paragraph of what you write.

The migration is the root cause, and the question is not how the policy got there but whether anything else from that migration carries the same pattern. Go and check the rest.

Advise the business on facts and uncertainty, not on a verdict. Whether this is a notifiable breach is a legal determination under whichever regimes apply, and your job is to give counsel the exposure window, the data categories, the discoverability finding and the honest limits of the evidence. Bring legal in early rather than after you have formed a view.

Enable access logging now even though it is nine months late, and say out loud why: so the next version of this conversation has an answer.', 0, '2026-11-22T07:15:26.590Z');
DELETE FROM scenario_points WHERE scenario_id = 'sc_cloud_public-bucket-no-logs';
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_cloud_public-bucket-no-logs_p1', 'sc_cloud_public-bucket-no-logs', 1, 'Closes the exposure without breaking production', 'Nine months is long enough for something legitimate to depend on anonymous read. Check before flipping it.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_cloud_public-bucket-no-logs_p2', 'sc_cloud_public-bucket-no-logs', 2, 'States plainly that absence of logs means no proof of non-access', 'The honest answer is that it cannot be proven. Letting the business believe otherwise is the real failure available in this scenario.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_cloud_public-bucket-no-logs_p3', 'sc_cloud_public-bucket-no-logs', 3, 'Goes after secondary evidence systematically', 'Control plane logs, CDN or load balancer logs, egress billing patterns. Weak evidence used carefully still narrows the picture.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_cloud_public-bucket-no-logs_p4', 'sc_cloud_public-bucket-no-logs', 4, 'Separates listing from reading', 'Public read with listing enabled is enumerable. Without listing, and with high-entropy object names, exposure is far narrower. This distinction drives everything after it.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_cloud_public-bucket-no-logs_p5', 'sc_cloud_public-bucket-no-logs', 5, 'Establishes the data categories in the bucket', 'What was in it determines who has to be told. Customer-uploaded documents could be anything, and "anything" is not an answer anyone can act on.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_cloud_public-bucket-no-logs_p6', 'sc_cloud_public-bucket-no-logs', 6, 'Checks whether the migration repeated the pattern elsewhere', 'The root cause is the migration, not the bucket. One instance found by accident usually means others not yet found.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_cloud_public-bucket-no-logs_p7', 'sc_cloud_public-bucket-no-logs', 7, 'Leaves the breach determination to legal, with facts attached', 'Notifiability is a legal call. Supplying the window, the categories, the discoverability finding and the evidential limits is the security contribution.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_cloud_public-bucket-no-logs_p8', 'sc_cloud_public-bucket-no-logs', 8, 'Enables logging now and says why', 'Late is better than never, and naming the reason makes it a control decision rather than an embarrassed reflex.');

INSERT OR REPLACE INTO scenarios (id, role, level, title, situation, ask, minutes, model_answer, is_free, created_at) VALUES ('sc_network_temp-any-any-rule', 'network', 'fresher', 'The temporary rule that is four years old', 'During a firewall rule review you find a rule permitting any protocol on any port from the office VLAN to the server VLAN. It was created four years ago. The comment field reads "temp - printer issue - remove after testing". The network lead agrees it looks wrong but is nervous about removing it, because nobody knows what has grown to depend on it.', 'Write your plan to remove it safely.', 20, 'Do not delete it. Everyone can see it should not exist, and that is not the same as knowing what is currently flowing through it. Four years is long enough for real production traffic to have settled into a hole nobody meant to leave open, and deleting it blind is how a security improvement becomes an outage with your name on it.

Measure first. Enable logging on that rule and leave it alone. You are not trying to be quick here, you are trying to be right, and the output of this step is a list of actual source and destination pairs with ports, rather than a list of what people believe they need.

Watch for a period that is genuinely representative. A week is almost never enough. Month end has traffic that no other week has, and so do payroll runs, backup windows, patch cycles and quarterly reporting. If you narrow this rule based on a quiet fortnight you will break something on the last working day of the month, which is the worst possible day for it to break.

Build the replacement from what you observed, not from what you were told. Ask the owners too, because observation will not tell you about the annual process that has not run yet, but treat what they say as an addition to the measured list rather than a substitute for it.

Then narrow in stages. Replace any-any with the observed set, keep logging on, watch, and then tighten again. Two or three deliberate steps are much safer than one confident one, and each step is individually easy to reverse.

Write the rollback down so that someone who is not you can execute it at two in the morning without making a judgement call. A rollback that only works if the person who designed the change is awake is not a rollback.

The comment is the lesson worth raising. Someone wrote "remove after testing" in good faith and there was no mechanism to make that happen. Temporary rules need an owner and an expiry date enforced by the process, because a comment field has never once removed a rule.', 0, '2026-11-22T07:15:26.590Z');
DELETE FROM scenario_points WHERE scenario_id = 'sc_network_temp-any-any-rule';
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_network_temp-any-any-rule_p1', 'sc_network_temp-any-any-rule', 1, 'Refuses to delete it blind', 'Obviously wrong and safe to remove are different claims. Four years of drift means something real is probably using it.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_network_temp-any-any-rule_p2', 'sc_network_temp-any-any-rule', 2, 'Turns on logging and measures before changing anything', 'The output needed is observed source, destination and port pairs, not a list of what people think they need.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_network_temp-any-any-rule_p3', 'sc_network_temp-any-any-rule', 3, 'Picks a representative window, not a convenient one', 'Month end, payroll, backups, patch windows, quarterly reporting. A quiet fortnight produces a rule that breaks on the worst day of the month.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_network_temp-any-any-rule_p4', 'sc_network_temp-any-any-rule', 4, 'Builds the replacement from observed flows', 'Asking owners is a supplement for the annual job that has not run yet, not a substitute for measurement.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_network_temp-any-any-rule_p5', 'sc_network_temp-any-any-rule', 5, 'Narrows in stages with logging left on', 'Two or three deliberate steps, each individually reversible, beats one confident change.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_network_temp-any-any-rule_p6', 'sc_network_temp-any-any-rule', 6, 'Writes a rollback someone else can run at 2am', 'A rollback that needs its author awake and thinking is not a rollback.');
INSERT INTO scenario_points (id, scenario_id, ord, label, detail) VALUES ('sc_network_temp-any-any-rule_p7', 'sc_network_temp-any-any-rule', 7, 'Raises expiry and ownership as the real fix', 'The comment field was written in good faith and nothing acted on it. Temporary rules need enforced expiry, because comments have never removed a rule.');
